  "Şampiyon maddesi: PPV gelir payı ve ana maç garantisi": "Klauzula mistrzowska: udział w PPV i gwarancja walki wieczoru",
  "Rüya gerçek oldu. Dünyanın en büyük sahnesi.": "Marzenie się spełniło. Największa scena świata.",
  " Büyük organizasyonlar kapıda!": " Duże organizacje pukają do drzwi!",
  "Mevcut organizasyonun seni tutmak istiyor.": "Twoja obecna organizacja chce cię zatrzymać.",
  "Şampiyonluğun Dean Wyatt’ın dikkatini çekti. DWCS’ye davetlisin. Kazanırsan ve etkilersen UCC kapısı açılır.": "Twoja droga po tytuł zwróciła uwagę Deana Wyatta. Jesteś zaproszony do DWCS. Wygraj i zrób wrażenie, a drzwi UCC się otworzą.",
  "Zirvedeki performansın izleniyor. Tek dövüş, tek şans: etkilersen UCC kontratı.": "Twoje występy w czołówce są obserwowane. Jedna walka, jedna szansa: zrób wrażenie, a będzie kontrakt z UCC.",
  "Mevcut organizasyonun yeni bir kontrat sunuyor.": "Twoja obecna organizacja oferuje nowy kontrakt.",
  "UCC yeni kontrat masaya koydu ({0} maaş basamağı).": "UCC położyło na stole nowy kontrakt (próg płacowy {0}).",
  "VIP MMA, UCC’den ayrılırsan büyük para vaat ediyor.": "VIP MMA obiecuje duże pieniądze, jeśli odejdziesz z UCC.",
  "Dean Wyatt’ın davetini geri çevirdin. {0} kontratına sadık kaldın.": "Odrzuciłeś zaproszenie Deana Wyatta. Zostałeś wierny kontraktowi z {0}.",
