  "İyi ama yeterli değil. Biraz daha bastır.": "Dobrze, ale za mało. Dociśnij trochę mocniej.",
  "Kartlarda öndeyiz sanırım. Riske girme ama geri de durma.": "Chyba prowadzimy na kartach. Nie ryzykuj, ale się nie cofaj.",
  "Başa baş gidiyor. Bir şeyi değiştirmemiz lazım.": "Łeb w łeb. Musimy coś zmienić.",
  "Çok yakın bir raunttu, kimin aldığı belli değil.": "Bardzo wyrównana runda, trudno powiedzieć, kto ją wziął.",
  "Ortada kaldık. Bu raunt farkı açmalısın.": "Utknęliśmy pośrodku. W tej rundzie musisz odskoczyć.",
  "Denk gidiyor, fark yaratacak olan sensin.": "Jest remis, to ty musisz zrobić różnicę.",
  "Bu raundu kaybettik, dinle beni! Planı değiştiriyoruz.": "Przegraliśmy tę rundę, słuchaj mnie! Zmieniamy plan.",
  "Uyan! Bu gidişle kartlar onun!": "Obudź się! W tym tempie karty są jego!",
  "Kötü raunt. Unut onu, sıfırdan başla.": "Zła runda. Zapomnij o niej, zacznij od nowa.",
  "Onun oyununu oynuyoruz. Hemen değiştir!": "Gramy w jego grę. Zmień to teraz!",
  "sürekli üstüne yürüyor": "ciągle spycha cię do tyłu",
