  "\"Tahmin edilebilir olma. Karıştır.\"": "„Nie bądź przewidywalny. Mieszaj”.",
  "\"Nefesin gitmiş! Tempoyu düşür, akıllı dövüş.\"": "„Jesteś wypompowany! Zwolnij, walcz mądrze”.",
