  "Düşük risk. Kazanman beklenir, fazla ses getirmez.": "Niskie ryzyko. Jesteś faworytem, nie zrobi to dużo szumu.",
  "Düşük risk, düşük getiri. Kazanırsan sıralamada az ilerlersin, kaybedersen ciddi düşersin.": "Niskie ryzyko, niska nagroda. Wygrasz, to trochę awansujesz; przegrasz, to mocno spadniesz.",
  "Dengeli eşleşme. Kazanan bir basamak yukarı çıkar.": "Wyrównane zestawienie. Zwycięzca wchodzi szczebel wyżej.",
  "Yüksek risk! Kazanırsan büyük sıçrama yaparsın, kaybedersen kimse şaşırmaz.": "Wysokie ryzyko! Wygrasz, to zrobisz wielki skok; przegrasz, nikt się nie zdziwi.",
  "⚔️ EZELİ RAKİP": "⚔️ ARCYRYWAL",
