  " (Patronla ilişki {0}{1})": " (Relacja z szefem {0}{1})",
  "📞 {0} arıyor": "📞 Dzwoni {0}",
  "Muhteşem bir performanstı evlat!": "Fantastyczny występ, młody!",
  "İşte benim istediğim dövüş buydu!": "Właśnie takiej walki chciałem!",
  "Salon hâlâ seni konuşuyor.": "Hala wciąż o tobie mówi.",
  "{0} {1}: “{2} Sana özel {3} bonus gönderiyorum.”": "{0} {1}: „{2} Wysyłam ci specjalny bonus {3}”.",
  "Teşekkür et": "Podziękuj",
  "Daha büyük bir maç iste": "Poproś o większą walkę",
  "Maaş zammı iste": "Poproś o podwyżkę",
  "Bonusu aldın ve içtenlikle teşekkür ettin. +{0}": "Wziąłeś bonus i szczerze podziękowałeś. +{0}",
  "{0} {1} ile seni eşleştirmeyi düşüneceğim.": "Pomyślę o zestawieniu cię z {0} {1}.",
  "Bakalım neler yapabiliriz.": "Zobaczymy, co da się zrobić.",
  "“Hırsını seviyorum. {0}” +{1}": "„Kocham ten głód. {0}” +{1}",
  "“Hak ettin.” Dövüş başı ücretin %15 arttı: {0}. +{1}": "„Zasłużyłeś”. Twoja gaża za walkę wzrosła o 15%: {0}. +{1}",
  "“Bonusla yetin evlat. Zam, kontrat masasında konuşulur.” +{0}": "„Ciesz się bonusem, młody. O podwyżkach rozmawiamy przy stole kontraktowym”. +{0}",
  "📞 {0}: “Konuşmamız lazım.”": "📞 {0}: „Musimy porozmawiać”.",
  "{0}: “Son iki maç kabul edilemez. Sana inanıyorum ama sabrım sınırsız değil. Bir yenilgi daha olursa yollarımızı ayırmak zorunda kalabilirim.”": "{0}: „Ostatnie dwie walki są nie do przyjęcia. Wierzę w ciebie, ale moja cierpliwość ma granice. Jeszcze jedna porażka i możemy się rozstać”.",
  "Söz veriyorum, döneceğim": "Obiecuję, wrócę",
  "Kampımı baştan kuracağım": "Odbuduję obóz od zera",
  "Bana saygı göster!": "Okaż mi trochę szacunku!",
  "“Sözünü tut.” Telefonu kapattıktan sonra salona koştun. (Motivasyon tam)": "„Dotrzymaj słowa”. Po rozmowie pobiegłeś na salę. (Motywacja na maksimum)",
  "“Doğru adım.” Patron yaklaşımını beğendi.": "„Dobry ruch”. Szefowi spodobało się twoje podejście.",
  "“Öyle mi? Bu kontratın son maçı olsun o zaman.” Kontratında sadece 1 dövüş kaldı!": "„Tak? To niech to będzie ostatnia walka na kontrakcie”. Na kontrakcie została tylko 1 walka!",
  "“Saygı kazanılır.” Telefonu yüzüne kapattı.": "„Na szacunek się zasługuje”. Rozłączył się.",
  "📞 {0}: Acil durum!": "📞 {0}: Nagła sprawa!",
  "{0}: “Ana karttaki dövüşçülerden biri sakatlandı. 3 hafta sonra kafese girebilir misin? Kabul edersen normal ücretine ek {1} veririm ve bunu unutmam.”": "{0}: „Jeden z zawodników karty głównej doznał kontuzji. Możesz wejść do klatki za 3 tygodnie? Jeśli się zgodzisz, dam ci {1} ponad normalną gażę i nie zapomnę tego”.",
  "Kabul et, hazırım": "Zgadzam się, jestem gotowy",
  "Kampsız dövüşmem, reddet": "Bez obozu nie, odmawiam",
  "“İşte savaşçı!” Kısa haber primi +{0}. Sıradaki dövüşün 3 haftalık kısa kampla gelecek.": "„To jest zawodnik!” Bonus za zastępstwo +{0}. Następna walka z krótkim, 3-tygodniowym obozem.",
  "“Anlıyorum… ama bunu hatırlayacağım.”": "„Rozumiem… ale zapamiętam to”.",
  "🍽️ {0}’dan davet": "🍽️ Zaproszenie od {0}",
  "{0} {1} seni özel bir akşam yemeğine davet ediyor. {2}": "{0} {1} zaprasza cię na prywatną kolację. {2}",
  "Katıl": "Przyjdź",
  "Uzun bir sohbet oldu. Organizasyonun geleceğinde senin yerin konuşuldu.": "Długa rozmowa. Omówiono twoje miejsce w przyszłości organizacji.",
  "Patron sana gençliğinden hikâyeler anlattı. Aranızda güven oluştu.": "Szef opowiadał historie z młodości. Zaufanie między wami wzrosło.",
  " (Popülerlik +1)": " (Popularność +1)",
  "Kampa odaklanman gerektiğini söyledin. Anlayışla karşıladı.": "Powiedziałeś, że musisz skupić się na obozie. Zrozumiał.",
  "📞 {0}: “Bir maç fikrim var.”": "📞 {0}: „Mam pomysł na walkę”.",
  "{0} “{1}” {2} (#{3}) ile dövüşmeni istiyorum.": "Chcę, żebyś zawalczył z {0} „{1}” {2} (#{3}).",
  "Sıklette yukarıdan biriyle dövüşmeni istiyorum.": "Chcę, żebyś zawalczył z kimś wyżej w dywizji.",
  "{0}: “{1} Taraftar bunu görmek istiyor. Var mısın?”": "{0}: „{1} Fani chcą to zobaczyć. Wchodzisz?”",
  "Varım!": "Wchodzę!",
  "Şimdi değil": "Nie teraz",
  "“İşte bunu duymak istiyordum.” Maç masaya kondu.": "„Tego chciałem usłyszeć”. Walka jest na stole.",
  "“Tamam, ama fırsatlar beklemez.”": "„Dobrze, ale okazje nie czekają”.",
  "📞 {0}: Sosyal medya": "📞 {0}: Media społecznościowe",
  "Bizde saygı esastır, bu tavrı sevmiyorum.": "Szacunek to tu podstawa, nie podoba mi się ta postawa.",
  "Biraz daha ateşli ol, bilet satsın!": "Bądź trochę bardziej ognisty, sprzedaj trochę biletów!",
  "{0}: “Paylaşımlarını görüyorum. {1}”": "{0}: „Widzę twoje posty. {1}”",
  "Haklısın, dikkat edeceğim": "Masz rację, będę uważał",
  "Ben böyleyim": "Taki już jestem",
  "Patron memnun kaldı.": "Szef był zadowolony.",
  "“O zaman kendi yolunu çiz.”": "„To wyznacz własny kurs”.",
  "“İşte bu! Bilet satıyorsun.” (Popülerlik +2)": "„O to chodzi! Sprzedajesz bilety”. (Popularność +2)",
  "📜 {0}: Erken uzatma": "📜 {0}: Wczesne przedłużenie",
  "{0}: “Seninle uzun yola çıkmak istiyorum. Kontratını şimdiden 3 dövüş uzatalım, dövüş başı ücretine %20 zam.”": "{0}: „Chcę iść z tobą długą drogą. Przedłużmy od razu twój kontrakt o 3 walki, z podwyżką 20% za walkę”.",
  "İmzala": "Podpisz",
  "Serbest piyasayı görmek istiyorum": "Chcę sprawdzić wolny rynek",
  "İmzaladın! Yeni ücret {0}, kalan {1} dövüş.": "Podpisałeś! Nowa gaża {0}, pozostało {1} walk.",
  "“Kapım açık, ama sonsuza kadar değil.”": "„Moje drzwi są otwarte, ale nie na zawsze”.",
  "📉 Pound for Pound listesinden düştün.": "📉 Wypadłeś z listy Pound for Pound.",
  "🌍 POUND FOR POUND! Dünyanın en iyi {0} dövüşçüsü arasına girdin: #{1}": "🌍 POUND FOR POUND! Jesteś wśród {0} najlepszych zawodników świata: #{1}",
  "👑 POUND FOR POUND KRALI! Artık sıklet fark etmeksizin dünyanın en iyisisin.": "👑 KRÓL POUND FOR POUND! Jesteś najlepszy na świecie bez względu na wagę.",
  "📈 P4P listesinde #{0}’{1} #{2}’{3} yükseldin.": "📈 Awansowałeś w rankingu P4P z #{0} na #{2}.",
  "📉 P4P listesinde #{0}’{1} #{2}’{3} geriledin.": "📉 Spadłeś w rankingu P4P z #{0} na #{2}.",
  "Köpek": "Pies",
  "Sadık, dev ve korkusuz. Sabah koşularının bekçisi.": "Wierny, ogromny i nieustraszony. Strażnik porannych biegów.",
  "Kaslı ve enerjik. Tam bir dövüşçü köpeği.": "Umięśniony i energiczny. Prawdziwy pies wojownika.",
  "Herkesin sevgilisi. Sosyal medyada yıldız olur.": "Ulubieniec wszystkich. Staje się gwiazdą mediów społecznościowych.",
  "Sibirya Husky": "Husky syberyjski",
  "Durmadan koşar. Kondisyon canavarı.": "Biega bez przerwy. Kondycyjny potwór.",
  "Zeki ve disiplinli. Evinin bekçisi.": "Mądry i zdyscyplinowany. Strażnik twojego domu.",
