  "Sokaktan kurtarılmış bir savaşçı.": "Wojownik uratowany z ulicy.",
  "Van Kedisi": "Kot van",
  "İki farklı renk göz, efsanevi zarafet.": "Oczy w dwóch kolorach, legendarna gracja.",
  "Tombul, sakin ve asil.": "Pulchny, spokojny i szlachetny.",
  "Ara Papağanı": "Ara",
  "Kuş": "Ptak",
  "Adını söylemeyi öğrenir. Maç günü bağırır.": "Uczy się wymawiać twoje imię. Krzyczy w dzień walki.",
  "Tavşan": "Królik",
  "Diğer": "Inne",
  "Sessiz ve sevimli bir ev arkadaşı.": "Cichy, uroczy współlokator.",
  "Kaplumbağa": "Żółw",
  "Senden uzun yaşayacak. Sabır öğretir.": "Przeżyje cię. Uczy cierpliwości.",
  "Arap Atı": "Koń arabski",
  "Çiftlikte binicilik. Pahalı ama prestijli.": "Jazda na ranczu. Drogi, ale prestiżowy.",
  "Tür bulunamadı.": "Nie znaleziono gatunku.",
  "Önce bir isim ver.": "Najpierw nadaj mu imię.",
  "Daha fazla hayvana bakamazsın (en fazla 6).": "Nie dasz rady opiekować się kolejnymi zwierzakami (maks. 6).",
  "🛍️ Yeni aile üyesi: {0} {1} ({2})": "🛍️ Nowy członek rodziny: {0} {1} ({2})",
  "{0} {1} artık seninle! Haftalık bakım ${2}.": "{0} {1} jest teraz z tobą! Tygodniowa opieka {2} $.",
  "{0} bu hafta zaten doya doya oynadı.": "{0} wybawił się już w tym tygodniu do woli.",
  "{0} ile oynadın. Kuyruğunu sallıyor! (Mutluluk +20)": "Pobawiłeś się z {0}. Ogon merda! (Szczęście +20)",
  "Veteriner için paran yetmiyor.": "Nie stać cię na weterynarza.",
  "{0} veterinerden sapasağlam döndü. (-${1})": "{0} wrócił od weterynarza zdrowy. (-{1} $)",
  "🐾 {0} hastalandı! Veterinere götürmen gerek.": "🐾 {0} zachorował! Musisz zabrać go do weterynarza.",
  "Kamp": "Obóz",
  "Meydan oku": "Wyzwanie",
