  "{ph} söylemiştim. Sıradaki! 👋": "Mówiłem, {ph}. Następny! 👋",
  "Bu gece bir şey kanıtladım. {ph}, iyi dövüştün ama yeterli değildi.": "Dziś coś udowodniłem. {ph}, walczyłeś dobrze, ale to nie wystarczyło.",
  "Kemer yolu devam ediyor. {ph} sadece bir basamaktı.": "Droga do pasa trwa. {ph} był tylko stopniem.",
  "{ph} bu gece daha iyiydi. Tebrikler şampiyon adayı. Geri döneceğim.": "{ph} był dziś lepszy. Gratulacje, przyszły mistrzu. Wrócę.",
  "Ders aldım. {ph} gerçek bir savaşçı. 🤝": "Lekcja odrobiona. {ph} to prawdziwy wojownik. 🤝",
  "Hakemler bu gece beni soydu. {ph} bunu biliyor.": "Sędziowie mnie dziś okradli. {ph} to wie.",
  "Şanslı yumruktu {ph}. Rövanşta gerçeği göreceksin.": "Szczęśliwy cios, {ph}. Prawdę zobaczysz w rewanżu.",
  "Tek kelime: RÖVANŞ. {ph} kaçmasın.": "Jedno słowo: REWANŻ. Niech {ph} nie ucieka.",
  "{p} maçını 5. kez izliyorum, hâlâ doyamadım 🔥": "Oglądam walkę {p} piąty raz i wciąż mi mało 🔥",
  "Babam 40 yıldır maç izler, “böylesini görmedim” dedi.": "Mój tata ogląda walki od 40 lat i powiedział „czegoś takiego nie widziałem”.",
  "Bu adamın posteri odamda artık 🥊": "Plakat tego zawodnika wisi już na mojej ścianie 🥊",
  "{p} sıkletin geleceği değil, bugünü!": "{p} to nie przyszłość dywizji, to teraźniejszość!",
  "O kombinasyon ne öyle?! Geri sar, geri sar!": "Co to była za kombinacja?! Przewiń, przewiń!",
  "Salon arkadaşlarımla izledik, ortalık yıkıldı 😂": "Oglądałem z kumplami z sali, było szaleństwo 😂",
  "{p} geleceğin şampiyonu!! 🔥🔥": "{p} to przyszły mistrz!! 🔥🔥",
  "Bu adamı izlemek bir zevk. Kemer an meselesi.": "Czysta przyjemność oglądania. Pas to kwestia czasu.",
  "{memleket} gurur duyuyor! 🇹🇷💪": "{memleket} jest dumne! 💪",
  "Az önce {p} maçını izledim, tüylerim diken diken.": "Właśnie obejrzałem walkę {p}, mam ciarki.",
  "Bir sonraki maçına bilet alıyorum, kimse beni durduramaz.": "Kupuję bilety na następną walkę, nikt mnie nie powstrzyma.",
  "Oyun planı felaketti. Hoca değişmeli.": "Plan walki to katastrofa. Trener musi odejść.",
  "Kötü gün herkesin başına gelir. {p} döner.": "Każdy ma gorszy dzień. {p} wróci.",
  "Bu kadar hype’a bu performans mı? 🤡": "Tyle hype'u za taki występ? 🤡",
  "{p} kampta tatil mi yaptı acaba?": "{p} pojechał na wakacje zamiast na obóz?",
  "Kafam hâlâ inanmıyor ya… ❤️‍🩹": "Wciąż nie mogę uwierzyć… ❤️‍🩹",
  "{p} abartılıyormuş, belli oldu.": "Chyba jednak {p} był przereklamowany.",
  "Üzülme {p}, büyük şampiyonlar da kaybeder. Kalk ayağa! ❤️": "Nie smuć się, {p}, wielcy mistrzowie też przegrywają. Wstawaj! ❤️",
  "Kamp değişmeli. Bu oyun planı neydi?": "Obóz musi się zmienić. Co to był za plan walki?",
  "Hâlâ arkandayız {p}. 💪": "Wciąż jesteśmy za tobą, {p}. 💪",
  "HAHAHA efsane 😂🔥": "HAHAHA legendarne 😂🔥",
  "Bu adamın ağzı da yumrukları kadar sert!": "Ten zawodnik ma tak twardy język jak ciosy!",
  "Gerilim tırmanıyor, bu maçı kaçırmam!": "Napięcie rośnie, nie przegapię tej walki!",
  "Önce bir kemer al, sonra konuş.": "Najpierw zdobądź pas, potem gadaj.",
  "Çok konuşan az dövüşür.": "Kto najwięcej gada, najmniej walczy.",
  "Bu biraz fazlaydı…": "To było trochę za dużo…",
