  "Amatör ligde resmi sıralama yok. Profesyonel olduğunda organizasyonunun sıklet sıralaması burada açılacak.": "W lidze amatorskiej nie ma oficjalnych rankingów. Gdy przejdziesz na zawodowstwo, pojawi się tu ranking dywizji twojej organizacji.",
  "Bu organizasyonda sıralama yok. Tek gecelik bir fırsat: kazanırsan kapılar açılır.": "Ta organizacja nie ma rankingu. Szansa jednego wieczoru: wygraj, a drzwi się otworzą.",
