  "Karakterini Nasıl Kurarsın?": "Jak zbudować postać?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Narodowość: możliwości treningowe ustalają startowe statystyki, wsparcie kibiców startową popularność. Od kraju zależą też pierwsza sala i trener.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Wiek (18-30): Zaczniesz młodo, będziesz surowy, ale szybko się rozwiniesz (×1,3). Zaczniesz później, będziesz silniejszy, ale po 32. roku życia szybkość i szczęka zaczną słabnąć. W wieku 41 lat emerytura jest nieunikniona.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Kategoria wagowa: lżejsze wagi są szybkie i wytrzymałe, ciężcy biją mocno, ale szybko się męczą.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Zaplecze: najważniejszy wybór. Ustala mocne i słabe strony, a więc i to, jak walczysz.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Historia: napisz ją sam albo pozwól, żeby napisała ją gra.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Kość: w ostatnim kroku losowane są statystyki. Nie podobają ci się? Możesz losować ponownie dwa razy.",
  "Gelişim Puanı": "Punkty rozwoju",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Karierę zaczynasz z 3 punktami. Każdy obóz daje 1-3 punkty (zależnie od intensywności, wieku, miejsca obozu, jakości trenera i sztabu). Obszar fokusu obozu też rośnie o +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Walki też dają punkty: zwycięstwo 2, skończenie +1, bonus +1, pas +1. Porażka i remis 1 punkt.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Cykl walki (obóz + regeneracja) trwa około 90-100 dni. Walczysz 3-4 razy w roku; każda decyzja się liczy.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Wydawaj punkty na dowolne statystyki. Do 50 +1 kosztuje 1 punkt; do 70 – 2; do 85 – 3; powyżej – 4 punkty.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Możesz je wydać przed ważeniem na koniec obozu, po walce albo w zakładce ROZWÓJ na ekranie Kariery.",
  "Nasıl Oynanır?": "Jak grać",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Wybierz rywala. Na etapie regionalnym wybierasz ty; w dużych organizacjach rywal jest przydzielany.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Obóz: obszar fokusu, plan walki, intensywność, zbijanie wagi i konferencja prasowa. Plan walki celujący w słabość rywala daje w klatce dużą przewagę.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Walka: w każdej rundzie wybierasz taktykę. W krytycznych momentach (rywal wstrząśnięty, złapane poddanie) podejmujesz szybkie decyzje.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Potem: bonusy, wywiad, ranking, oferty kontraktów i wydarzenia między walkami.",
