  "Burası senin köşen": "To twój narożnik",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Na górze masz pieniądze, zdrowie i popularność. Gdy będziesz gotowy, wybierz rywala przez „ZORGANIZUJ WALKĘ”. Między walkami czekają sklep, media społecznościowe i życie nocne; ale pamiętaj, wszystko ma swoją cenę.",
  "Gelişim puanları": "Punkty rozwoju",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Punkty zdobywasz na obozach i w walkach, a tu rozdzielasz je na statystyki. Powyżej 50 każdy punkt kosztuje więcej; łatanie słabości to zwykle mądrzejszy ruch.",
  "Rakibini seç": "Wybierz rywala",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Przy każdym rywalu widać jego siłę i słabość. Łatwy rywal jest bezpieczny, ale mało daje; pokonaj ryzykownego, a zrobisz wielki skok w rankingu.",
  "Kamp başlıyor": "Obóz się zaczyna",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Najpierw wybierz długość obozu. Długi obóz bardziej rozwija, ale więcej kosztuje i męczy. W wolnych tygodniach przed obozem możesz szlifować technikę i sparować.",
  "Oyun planı": "Plan walki",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Plan dopasowany do słabości rywala podwaja swój efekt w walce. Sprawdź raport zwiadowczy i wybierz plan.",
  "Burun buruna": "Twarzą w twarz",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Po ważeniu staniesz twarzą w twarz z rywalem. Twoja postawa może go złamać albo drogo cię kosztować.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Na początku każdej rundy wybierz taktykę, a walka toczy się sama. Gdy rywal jest wstrząśnięty albo otwiera się poddanie, musisz szybko decydować. Pilnuj kondycji: gdy się zmęczysz, wszystko jest trudniejsze.",
  "Dövüş bitti": "Walka skończona",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "Mikrofon jest twój: to, co powiesz w wywiadzie, wpływa na popularność. Zdobyte punkty wydaj w zakładce ROZWÓJ. Piękne zwycięstwo? Udostępnij, niech wszyscy zobaczą!",
