  "Masaya \"sol kroşem zayıf\" yazan bir kâğıt bıraktın. Yem atıldı.": "Zostawiłeś na stole kartkę \"mój lewy sierpowy jest słaby\". Przynęta zarzucona.",
  "Halatın tepesine ilk sen çıktın! Takımın kazandı: +$5.000, ekran süresi +8.": "Pierwszy wspiąłeś się na linę! Twoja drużyna wygrała: +5000 $, czas antenowy +8.",
