  "🧠 Ağır darbeler aldın. Beyin hasarı +{0} ({1}/100).": "🧠 Przyjąłeś ciężkie ciosy. Uszkodzenie mózgu +{0} ({1}/100).",
  "🩺 Doktor seni muayeneye çağırıyor. Sonuçlar kariyer ekranında.": "🩺 Lekarz wzywa cię na badania. Wyniki na ekranie kariery.",
