  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Gdy rywal szykuje cios, wokół jego głowy kurczy się pierścień. Gdy zrobi się ZŁOTY, wciśnij UNIK i od razu bij: kontry zadają podwójne obrażenia.",
  "Vur ve kes": "Bij i przerywaj",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "JAB jest szybki i tani, PROSTY i KOPNIĘCIE są ciężkie. Rzuć PROSTY lub KOPNIĘCIE w trakcie zamachu, by go przerwać. Żółty pasek to kondycja: gdy się skończy, ciosy słabną.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Próbuj SPROWADZENIA; gdy on wchodzi z ⬇️, zrób sprawl przyciskiem UNIK. W parterze przyciski się zmieniają: z góry bij i szukaj dźwigni, z dołu przy 🔒 od razu UCIEKAJ.",
