  "Maç bir türlü yapılmadı. {0} her yerde “benden kaçtı” diyor. Taraftarların bir kısmı ona inanıyor.": "Walka się nie odbyła. {0} wszędzie mówi „uciekł przede mną”. Część fanów mu wierzy.",
  "Umursama": "Zignorować",
  "Kafeste rakip, kafes dışında centilmen. Herkes bu fotoğrafı paylaştı. Popülerlik +4, IQ +1.": "Rywal w klatce, dżentelmen poza nią. Wszyscy udostępnili to zdjęcie. Popularność +4, IQ +1.",
  "Sözün bitti. Taraftar bu soğukluğa bayıldı. Popülerlik +2, motivasyon +1.": "Słowa się skończyły. Fani pokochali ten chłód. Popularność +2, motywacja +1.",
  "“Bir gün yine karşılaşacağız.” Bu öfke kampa yakıt oldu. Motivasyon +2, popülerlik +2.": "„Kiedyś jeszcze się spotkamy”. Ta złość napędziła obóz. Motywacja +2, popularność +2.",
  "Kaseti yüz kez izledin. Nerede hata yaptığını artık biliyorsun. Motivasyon +2, IQ +1.": "Obejrzałeś nagranie sto razy. Teraz wiesz, gdzie popełniłeś błąd. Motywacja +2, IQ +1.",
  "Bir süre konuşuldu, sonra unutuldu. Popülerlik -2.": "Przez chwilę o tym mówiono, potem zapomniano. Popularność -2.",
  "👴 Salondaki Yaşlı Adam": "👴 Starzec na sali",
  "Bir haftadır her sabah salonun köşesinde biri seni izliyor. Sonunda öğreniyorsun: {0}, yıllar önce kemerini bırakmadan emekli olan efsane. Yanına gelip yalnızca “Ayakların yanlış.” diyor.": "Od tygodnia ktoś co rano obserwuje cię z kąta sali. W końcu się dowiadujesz: to {0}, legenda, która lata temu odeszła, nie tracąc pasa. Podchodzi i mówi tylko: „Złe ustawienie stóp”.",
  "Ondan ders iste": "Poprosić o lekcje",
  "Teşekkür et, yoluna devam et": "Podziękować i iść dalej",
  "{0} başını salladı ve bir daha gelmedi. Bazı kapılar bir kez açılır.": "{0} skinął głową i więcej nie przyszedł. Niektóre drzwi otwierają się tylko raz.",
  "İlk ders bir saat sürdü, tek bir yumruk bile atmadın. Sadece ayak. IQ +1.": "Pierwsza lekcja trwała godzinę i nie zadałeś ani jednego ciosu. Tylko praca nóg. IQ +1.",
  "⛰️ Dağ Kampı": "⛰️ Obóz w górach",
  "{0} seni bir haftalığına köyündeki eski ahıra götürüyor. Telefon yok, ayna yok. “Neyi düzeltmek istiyorsun?” diye soruyor.": "{0} zabiera cię na tydzień do starej stodoły w swojej wsi. Bez telefonu, bez lustra. „Co chcesz poprawić?” — pyta.",
  "Vuruşlarımı: odun ve kum torbası": "Uderzenia: drewno i worek",
  "Güreşimi: köyün pehlivanlarıyla": "Zapasy: z wiejskimi zapaśnikami",
  "Kafamı: sessizlik ve nefes": "Głowę: cisza i oddech",
  "Bir hafta boyunca balta salladın. Yumrukların artık başka ses çıkarıyor. Vuruş +2.": "Tydzień machania siekierą. Twoje ciosy brzmią teraz inaczej. Uderzenia +2.",
  "Köyün pehlivanları seni her gün çimene gömdü. Sonra sen onları. Güreş +2.": "Wiejscy zapaśnicy codziennie wbijali cię w trawę. Potem ty ich. Zapasy +2.",
  "Gün doğumunda nefes, gün batımında sessizlik. Kafes artık o kadar gürültülü gelmiyor. IQ +2.": "Oddech o świcie, cisza o zachodzie. Klatka nie wydaje się już tak głośna. IQ +2.",
  "🏥 Hastane Koridoru": "🏥 Szpitalny korytarz",
  "{0} kalp krizi geçirdi. Durumu iyi ama yorgun. Elini tutup fısıldıyor: “Bir sonraki maçında köşende olmak istiyordum…”": "{0} przeszedł zawał. Jest stabilny, ale zmęczony. Trzymając cię za rękę, szepcze: „Chciałem być w twoim narożniku na następnej walce…”",
  "Maçı ona ada": "Zadedykować mu walkę",
  "Kampı bırak, yanında kal": "Zostawić obóz, zostać przy nim",
  "Eldivenlerinin üstüne onun adını yazdırdın. Motivasyon +2.": "Kazałeś wypisać jego imię na rękawicach. Motywacja +2.",
  "Bir hafta hastane koridorunda uyudun. Antrenman aksadı ama içindeki bir şey yerine oturdu. Motivasyon +1, kondisyon -1.": "Przez tydzień spałeś na szpitalnym korytarzu. Trening ucierpiał, ale coś w tobie wskoczyło na miejsce. Motywacja +1, kondycja -1.",
  "✉️ Son Ders": "✉️ Ostatnia lekcja",
  "O gece {0} hastane odasında maçını izlemiş. Hemşire, kazandığın anda yatağından doğrulduğunu anlatıyor. Sana bir zarf bırakmış.": "Tej nocy {0} oglądał twoją walkę w szpitalnej sali. Pielęgniarka mówi, że usiadł na łóżku w chwili twojej wygranej. Zostawił ci kopertę.",
  "{0} maçını hastane odasında izlemiş. Kaybettin ama ertesi sabah sana bir zarf göndermiş.": "{0} oglądał twoją walkę ze szpitala. Przegrałeś, ale następnego ranka przysłał ci kopertę.",
  "“Ayakların artık doğru. Gerisi senin.” Mektubu çerçeveletip salonun duvarına astın. IQ +1, popülerlik +{0}.": "„Stopy masz już dobrze. Reszta należy do ciebie”. Oprawiłeś list i powiesiłeś na ścianie klubu. IQ +1, popularność +{0}.",
  "“Kaybetmek, ayaklarını yeniden bulmaktır. Yarın sabah altıda salondayım.” Ve oradaydı. IQ +1, popülerlik +{0}.": "„Przegrać to znów odnaleźć grunt pod stopami. Jutro o szóstej jestem na sali”. I był. IQ +1, popularność +{0}.",
  "✏️ Bir Mektup": "✏️ List",
  "Memleketinden on iki yaşında bir çocuk yazmış: “Adım {0}. Okulda bana vuruyorlar. Senin gibi olmak istiyorum. Bana bir şey öğretir misin?” Mektubun köşesinde senin bir çizimin var.": "Dwunastolatek z twojego miasta napisał: „Nazywam się {0}. W szkole mnie biją. Chcę być taki jak ty. Nauczysz mnie czegoś?” W rogu listu jest twój rysunek.",
  "Mahalleye git ({0})": "Odwiedzić osiedle ({0})",
  "İmzalı eldiven gönder": "Wysłać podpisane rękawice",
  "Eldiveni alınca annesi bir video gönderdi: {0} eldivenlerle uyuyor. Popülerlik +1.": "Gdy rękawice dotarły, jego mama przysłała nagranie: {0} śpi w nich. Popularność +1.",
  "Mahalle sahasında yüz çocuk seni bekliyordu. {0} en öndeydi, elini hiç bırakmadı. Motivasyon +1.": "Setka dzieci czekała na osiedlowym boisku. {0} stał na przedzie i nie puszczał twojej ręki. Motywacja +1.",
  "🚨 Kötü Haber": "🚨 Złe wieści",
  "{0} adlı çocuğun annesi aradı. Oğlu mahalledeki bir çeteyle takılmaya başlamış, dün gece karakoldan almışlar. “Seni dinler” diyor.": "Zadzwoniła mama {0}. Syn zaczął trzymać się z osiedlowym gangiem, wczoraj odbierali go z komisariatu. „Ciebie posłucha” — mówi.",
  "Onu salona yazdır ({0})": "Zapisać go do klubu ({0})",
  "Telefonla konuş": "Porozmawiać przez telefon",
  "Bir yıllık salon üyeliğini ödedin. Hocası “ilk hafta üç kez kustu ama bırakmadı” diyor. Popülerlik +2.": "Opłaciłeś rok w klubie. Trener mówi: „w pierwszym tygodniu trzy razy wymiotował, ale nie odpuścił”. Popularność +2.",
  "Bir saat konuştunuz. Sonunda “Tamam abi” dedi. Ne kadar sürer, bilinmez.": "Rozmawialiście godzinę. W końcu powiedział: „Dobra, stary”. Kto wie, na jak długo.",
  "🥇 İlk Madalya": "🥇 Pierwszy medal",
  "{0} bölge çocuk güreş turnuvasında finale çıktı. Maçtan önce sana bir ses kaydı gönderiyor: “Seni hep izledim, bugün sen beni izle.”": "{0} dotarł do finału regionalnego turnieju zapaśniczego dzieci. Przed walką wysyła ci nagranie: „Zawsze oglądałem ciebie. Dziś ty obejrzyj mnie”.",
  "Canlı izle, ekrana bağır": "Oglądać na żywo, krzyczeć do ekranu",
  "📸 Bir Fotoğraf": "📸 Zdjęcie",
  "{0} adlı çocuğun annesi bir fotoğraf gönderdi: Oğlu okul takımına girmiş. Arkasında senin posterin.": "Mama {0} przysłała zdjęcie: syn dostał się do szkolnej drużyny. Za nim twój plakat.",
  "Kısa bir video mesajı çek": "Nagrać krótką wiadomość wideo",
  "📰 {0} adlı dövüşçünün desteklediği çocuk madalyayla döndü: “Abim gibi olacağım.”": "📰 Dzieciak wspierany przez {0} wrócił z medalem: „Będę jak mój starszy brat”.",
  "{0} altın madalyayı boynunda sana gösterdi. Video milyonlarca izlendi. Popülerlik +4, motivasyon +1.": "{0} pokazał ci złoty medal na szyi. Nagranie obejrzały miliony. Popularność +4, motywacja +1.",
  "Videoyu bütün okul izlemiş. {0} artık “kafesteki abinin kardeşi”. Popülerlik +2.": "Cała szkoła obejrzała nagranie. {0} to teraz „młodszy brat wojownika z klatki”. Popularność +2.",
