  "Her şeyin başladığı gece. Eldivenler hâlâ terli kokuyor.": "Noc, w której wszystko się zaczęło. Rękawice wciąż pachną potem.",
  "Rakip yere düştüğünde salonun nasıl patladığını hâlâ duyuyorsun.": "Wciąż słyszysz, jak hala eksplodowała, gdy padł.",
  "Fotoğrafçı tam o anı yakaladı: rakibin eli minderde, senin yüzünde sakinlik.": "Fotograf uchwycił ten moment: jego dłoń na macie, spokój na twojej twarzy.",
  "Adın ilk kez büyük harflerle bir afişteydi.": "Twoje imię po raz pierwszy wielkimi literami na plakacie.",
