  "Kartlarda gerideydin. Bu bandajlarla maçı çevirdin.": "Przegrywałeś na kartach. W tych bandażach odwróciłeś walkę.",
  "Bahis şirketleri seni yazmamıştı bile. Gazete manşeti duvarında.": "Bukmacherzy cię skreślili. Nagłówek wisi na twojej ścianie.",
