  "Kafes dışında başlayan bir hikâye kafeste bitti.": "Historia, która zaczęła się poza klatką, skończyła się w niej.",
  "Altın ilk kez beline değdiğinde ağladın. Kameralar da gördü.": "Płakałeś, gdy złoto pierwszy raz dotknęło twojego pasa. Kamery też to widziały.",
  "Dünyanın en büyük sahnesi. En tepedesin.": "Największa scena świata. Jesteś na szczycie.",
  "Kemeri almak bir şey, tutmak başka.": "Zdobyć pas to jedno, utrzymać — drugie.",
