  "Gün doğumunda yüzlerce balon. Hayatında ilk kez kafan bu kadar sessizdi.": "Setki balonów o świcie. Pierwszy raz w życiu w głowie była taka cisza.",
  "Açık büfeden bir tabak. Arkasına antrenörün “Bunu görmedim.” yazmış.": "Talerz z bufetu. Trener dopisał z tyłu: „Nie widziałem tego”.",
  "Sörf tahtasıyla kumsalda. İlk dalgada düştün, onuncuda ayaktaydın.": "Na plaży z deską. Spadłeś na pierwszej fali, stanąłeś na dziesiątej.",
  "Bir gökdelenin tepesinden şehir. Ünlülerle çekilmiş fotoğraflar telefonunda.": "Miasto ze szczytu wieżowca. Telefon pełen zdjęć z gwiazdami.",
