  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Po treningu {0} wziął cię na bok: „Nie słuchasz mnie. Jeśli tak dalej, rozstańmy się”.",
