  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Przełknąłeś dumę. {0} skinął głową: „Jutro o szóstej”. Więź się odbudowuje, motywacja -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "Podwyżka pomogła, ale najważniejsza była rozmowa. Więź się wzmocniła.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Rozstałeś się z {0}. Nowy trener to {1}. Zaufanie trzeba zbudować od zera. Motywacja -1.",
  "🫂 Bir Baba Gibi": "🫂 Jak ojciec",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "Późnym wieczorem, sami na sali, {0} wyjął stare zdjęcie: twój pierwszy trening, rękawice większe niż dłonie. „Kiedy wszedłeś przez te drzwi, wiedziałem” — powiedział.",
  "Sarıl": "Uściskać go",
  "“Her şeyi sana borçluyum.”": "„Wszystko ci zawdzięczam”.",
  "{0} ile ilk antrenman fotoğrafı": "Zdjęcie z pierwszego treningu z {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Rękawice większe niż dłonie. Z tyłu pismem trenera: „Kiedyś”.",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Długo milczeliście. Nie było potrzeby. Motywacja +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "„Nie — powiedział — wszystko zawdzięczasz sobie. Ja tylko otworzyłem drzwi”. Motywacja +2.",
  "📨 Rakip Kampın Teklifi": "📨 Oferta rywalskiego obozu",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Duży klub zaproponował twojemu trenerowi {0} posadę głównego trenera za podwójną pensję. Nie powiedział ci; usłyszałeś od kogoś innego.",
  "Ona zam yap ve kalmasını iste ({0})": "Dać podwyżkę i poprosić, żeby został ({0})",
  "Onu tebrik et, gitmesine izin ver": "Pogratulować i pozwolić odejść",
  "Sessiz kal, kararı ona bırak": "Milczeć i zostawić decyzję jemu",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} odmówił: „Mój zawodnik jest tutaj”. Więź mocno się wzmocniła.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} odszedł ze łzami w oczach, przedstawiając ci nowego trenera {1}. Motywacja +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} został. „Powinienem był zdecydować bez pytania, ale to mój dom” — powiedział.",
