  "Kamera yokken de bu kadar cesur musun? Kafeste göreceğiz.": "Też jesteś taki odważny bez kamer? Zobaczymy w klatce.",
  "Senin videolarını izledim. Açığını buldum bile. 😴": "Obejrzałem twoje nagrania. Już znalazłem słaby punkt. 😴",
  "Ailene söyle, maçı izlemesinler. Üzülmesinler.": "Powiedz rodzinie, żeby nie oglądała. Szkoda ich nerwów.",
  "Basın toplantısında gülüyordun. Kafeste gülemeyeceksin.": "Śmiałeś się na konferencji. W klatce nie będzie ci do śmiechu.",
  "Bu maçtan sonra kimse adını hatırlamayacak.": "Po tej walce nikt nie zapamięta twojego nazwiska.",
  "Selam. Kampın iyi geçsin, sağlıklı gel. Kafeste en iyi hâllerimizle karşılaşalım. 🤝": "Cześć. Udanego obozu, przyjedź zdrowy. Spotkajmy się w klatce w najlepszej formie. 🤝",
  "Kariyerini uzun zamandır izliyorum. Bu maç ikimiz için de büyük fırsat. Başarılar.": "Od dawna śledzę twoją karierę. Ta walka to wielka szansa dla nas obu. Powodzenia.",
  "Basında ne derlerse desinler, sana saygım var. Maç günü görüşürüz.": "Niech prasa mówi co chce, szanuję cię. Do zobaczenia w dniu walki.",
