  "Cevap vermedin. Sinirini kampa sakladın: motivasyon +1.": "Nie odpisałeś. Złość zostawiłeś na obóz: motywacja +1.",
  "DM kavgası": "Kłótnia w DM",
  "Mesajlaşma kızıştı, kulise sızdı. Maçın gündemi yükseldi. Takipçi {0}.": "Wymiana zdań się zaogniła i wyciekła. Szum wokół walki rośnie. Obserwujący {0}.",
  "İfşa": "Ujawnienie",
  "Ekran görüntüsü yayıldı, herkes rakibin tehdidini konuşuyor. Takipçi {0}.": "Zrzut się rozszedł, wszyscy mówią o groźbie rywala. Obserwujący {0}.",
  "Saygıyla karşılık ver 🤝": "Odpowiedz z szacunkiem 🤝",
  "Alay et 😏": "Wyśmiej 😏",
  "Karşılıklı saygı. İçin rahat, kampa odaklandın: motivasyon +1, popülerlik +1.": "Wzajemny szacunek. Spokojna głowa, skupienie na obozie: motywacja +1, popularność +1.",
  "Alaycı DM": "Kpiący DM",
  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "Rywal to opublikował: „Okazałem szacunek, a dostałem to.” Szum wzrósł, ale część fanów ostygła. Obserwujący {0}.",
  "Promotör ofisi": "Biuro promotora",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Musimy sprzedać tę walkę. W przyszłym tygodniu możemy zrobić trasę prasową po 3 miastach. Męczące, ale bilety pójdą jak burza. Wchodzisz?",
  "Varım, tura çıkalım": "Wchodzę, ruszamy",
  "Kampı bölmem": "Nie przerywam obozu",
  "Basın turu": "Trasa prasowa",
  "Tur olay oldu, biletler kapışılıyor. Ama yol yorgunluğu kampı biraz bozdu: motivasyon -1. Takipçi {0}.": "Trasa była hitem, bilety znikają. Ale podróże zmęczyły: motywacja -1. Obserwujący {0}.",
  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "Promotor pomarudził, ale obóz został nienaruszony: motywacja +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "Kolacja we dwoje dziś, zanim zacznie się obóz? Potem nie zobaczę cię tygodniami. ❤️",
  "Tabii, rezervasyon benden": "Jasne, rezerwuję stolik",
  "Maçtan sonra telafi ederim": "Nadrobię po walce",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Piękny wieczór. Wchodzisz w obóz ze spokojną głową: motywacja +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "„Obiecujesz?” Obiecałeś. Nie zapomnij po walce.",
  "Annem": "Mama",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "Sąsiadka mówi, że znowu masz walkę. Jedz porządnie, nie głodź się dla wagi. Modlę się za ciebie.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Tata będzie oglądał na dużym ekranie, zaprosił całe osiedle. Uważaj na siebie, kochanie.",
  "Hemen ara 📞": "Zadzwoń od razu 📞",
  "“Merak etme anne” yaz": "Napisz „Nie martw się, mamo”",
  "Yarım saat konuştunuz. Sesini duymak iyi geldi: motivasyon +1.": "Rozmawialiście pół godziny. Jej głos dodał otuchy: motywacja +1.",
  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Napisała: „Dobrze, kochanie, niech Bóg cię prowadzi.” ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Mogę naśladować styl twojego rywala. Dodatkowy sparing wieczorem po zamknięciu sali? 🥊",
  "Yapalım": "Robimy",
  "Bu akşam dinlenmem lazım": "Muszę dziś odpocząć",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Ciężki, ale przydatny sparing. Więź się wzmocniła, trochę oberwałeś (zdrowie −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Napisał „Spoko, brachu.” Chyba trochę urażony.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Miałeś szczęście. Obaj to wiemy. W rewanżu zobaczysz prawdę.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Byłeś dziś lepszy, gratulacje. Kiedyś chcę rewanżu, ale najpierw się pozbieram. 🤝",
  "Saygılar, iyi dövüştün": "Szacunek, dobra walka",
