  "Rekabet kızışıyor. Bir gün yine karşılaşırsanız ortalık yanar.": "Rywalizacja się zaostrza. Jeśli znów się spotkacie, będzie ogień.",
  "Hocam": "Trener",
  "Kafana takma. Yarın sabah salona erken gel, maçı birlikte izleyelim. Neyi yanlış yaptığımızı ben de görmek istiyorum.": "Nie zadręczaj się. Przyjdź jutro wcześnie na salę, obejrzymy walkę razem. Też chcę zobaczyć, co zrobiliśmy źle.",
  "Sabah oradayım": "Rano będę",
  "Birkaç gün kafa dinleyeceğim": "Muszę odpocząć kilka dni",
  "Maçı kare kare izlediniz. Hocanla bağın güçlendi.": "Przeanalizowaliście walkę klatka po klatce. Więź z trenerem się wzmocniła.",
  "Biraz uzaklaştın, iyi geldi: motivasyon +1. Hocan biraz kırıldı.": "Trochę dystansu pomogło: motywacja +1. Trener jest nieco urażony.",
  "Gurur duydum. Ama şımarmak yok, pazartesi idmandayız. 😄": "Jestem dumny. Ale bez gwiazdorzenia, w poniedziałek trening. 😄",
