  "Hey şampiyon, büyük hayranınım! Bir sonraki maçına gelmek istiyorum. Bilet ayarlayabilir misin? 🙏": "Hej mistrzu, jestem wielkim fanem! Chcę przyjść na twoją następną walkę. Załatwisz bilet? 🙏",
  "Ön sıra benden 🎟️": "Pierwszy rząd ode mnie 🎟️",
