  "Kafes kenarında kameralar onu gösterecek, adın her yerde: popülerlik +1 (−{0}). Takipçi {1}.": "Kamery pokażą gwiazdę przy klatce, twoje nazwisko jest wszędzie: popularność +1 (−{0}). Obserwujący {1}.",
  "Menajerin halletti. Kibar ama mesafeli.": "Menedżer to załatwił. Uprzejmie, ale z dystansem.",
  "Hafta sonu kısa bir kaçamak? Sahil kasabası, telefonlar kapalı. 🌊": "Krótki wypad na weekend? Nadmorskie miasteczko, telefony wyłączone. 🌊",
