  "İki gün deniz, güneş ve sessizlik. Sağlık +4, motivasyon +1 (−{0}).": "Dwa dni morza, słońca i ciszy. Zdrowie +4, motywacja +1 (−{0}).",
  "“Anlıyorum ama sıradaki tatil benden” yazdı.": "Odpisała: „Rozumiem, ale następny wyjazd wybieram ja.”",
  "Senin portreni çizdim, üç gece uğraştım! 🎨 Beğenir misin?": "Narysowałem twój portret, trzy noce roboty! 🎨 Podoba ci się?",
