  "Kaşın açıldı, gözüne akan kanla dövüşmeye devam ettin.": "Rozcięty łuk brwiowy, walczyłeś dalej z krwią w oku.",
  "{0} yediği yumrukla yere gitti!": "{0} padł na deski po twoim ciosie!",
