  "Ya da bir efsaneyi yaşa": "Albo przeżyj historię legendy",
  "{0}: Dublin'den çifte şampiyonluğa, rehberli 9 bölüm. Ücretsiz.": "{0}: z Dublina po mistrzostwo dwóch kategorii, 9 rozdziałów z przewodnikiem. Za darmo.",
