  "Sıradaki bölüm: {0} ({1}). Önünde {2} bölüm daha var.": "Następny rozdział: {0} ({1}). Przed tobą jeszcze {2} rozdziałów.",
  "{0} hikâyesine kaldığın yerden devam et:": "Kontynuuj historię {0} od miejsca, w którym skończyłeś:",
  "Paket almadan da bu kariyere normal devam edebilirsin; yalnızca bölüm hedefleri ilerlemez.": "Możesz grać dalej tę karierę bez pakietu; tylko cele rozdziałów nie będą postępować.",
  "SIRADAKİ EFSANE": "NASTĘPNA LEGENDA",
  "ŞAMPİYONSUN. SIRADA EFSANELER VAR": "JESTEŚ MISTRZEM. CZAS NA LEGENDY",
  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Po zdobyciu pasa {0} pokazała światu kobiece MMA. Przeżyj jej drogę rozdział po rozdziale.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} nosił ten pas z niepokonanym rekordem 29-0. Przeżyj jego drogę rozdział po rozdziale.",
  "İstersen önce menüdeki Efsane Yolları'ndan her efsanenin 1. bölümünü ücretsiz dene.": "Rozdział 1 każdej legendy możesz zagrać za darmo w Drogach Legend w menu.",
  "{0} nasıl efsane oldu?": "Jak {0} został legendą?",
