  "🔒 {0} hikâyesinin devamı Efsaneler Paketi'nde. Kariyerine normal devam edebilirsin.": "🔒 Dalsza część historii {0} jest w Pakiecie Legend. Możesz normalnie kontynuować karierę.",
  "📖 EFSANE YOLU DEVAM EDİYOR: Bölüm {0}.": "📖 DROGA LEGENDY TRWA DALEJ: rozdział {0}.",
