  "Altın Seri ve Şampiyon çerçevesi": "Złota Seria i ramka Mistrza",
  "Şampiyon ol · {0}": "Zostań Mistrzem · {0}",
  "BUGÜN 3 REKLAM İZLEDİN": "OBEJRZAŁEŚ DZIŚ 3 REKLAMY",
  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "Z Pakietem Mistrza wszystkie nagrody od razu i bez reklam. Jednorazowy zakup, bez subskrypcji.",
  "BÜTÜN YUVALAR DOLU": "WSZYSTKIE MIEJSCA ZAJĘTE",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "Pakiet Mistrza daje 5 miejsc na kariery: nie musisz usuwać starej historii, by zacząć nową.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "PAKIET GODNY MISTRZA",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Zdobyłeś pas. Odblokuj wszystkie dodatki z Pakietem Mistrza.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Bez reklam i od razu z Pakietem Mistrza",
  "👑 ŞAMPİYON PAKETİ": "👑 PAKIET MISTRZA",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Dowolnych dwóch zawodników, dowolna kategoria, ile chcesz walk. Wystaw też własne legendy przeciw legendom.",
  "Hayalî Maç Stüdyosu": "Studio Walk Marzeń",
  "Rövanş": "Rewanż",
  "Yeni eşleşme": "Nowe starcie",
  "Hayalî Maçlar'a dön": "Wróć do Walk Marzeń",
  "HAYALÎ MAÇ STÜDYOSU": "STUDIO WALK MARZEŃ",
  "Kimi yöneteceksin?": "Kim pokierujesz?",
  "Rakibini seç.": "Wybierz rywala.",
  "Kırmızı köşe": "Czerwony narożnik",
  "Mavi köşe": "Niebieski narożnik",
  "Emekli olan dövüşçülerini emeklilik ekranından Efsanelerim'e ekleyebilirsin; burada efsanelere karşı dövüşürler.": "Emerytowanych zawodników dodasz do Moich Legend z ekranu emerytury; tutaj walczą z legendami.",
  "⭐ Efsanem": "⭐ Moja legenda",
  "Rakibi değiştir": "Zmień rywala",
  "Zirvedeki halleriyle · 5 raunt": "W szczytowej formie · 5 rund",
  "{0} vs {1}": "{0} vs {1}",
  "İstediğin iki dövüşçü, istediğin sıklet, sınırsız maç. Kendi efsanelerin de burada.": "Dowolnych dwóch zawodników, dowolna kategoria, bez limitu walk. Twoje legendy też tu są.",
  "⭐ Efsanelerinde · Hayalî Maç Stüdyosu'nda dövüşebilir": "⭐ W Moich Legendach · może walczyć w Studiu Walk Marzeń",
  "Efsanelerim dolu. 👑 Şampiyon Paketi ile 10 efsane.": "Moje Legendy są pełne. 👑 10 legend z Pakietem Mistrza.",
  "⭐ Efsanelerime ekle (Hayalî Maç Stüdyosu)": "⭐ Dodaj do Moich Legend (Studio Walk Marzeń)",
