  "{0} zirvedeki haliyle kaydedilsin; Hayalî Maç Stüdyosu'nda Conor'a, Khabir'e ve diğer efsanelere karşı dövüşsün.": "Zapisz {0} w szczytowej formie i wystaw przeciw Conorowi, Khabirowi i innym legendom w Studiu Walk Marzeń.",
