  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Ta noc nigdy nie wyszła ci z głowy. Duszenie, cicha hala, ludzie skaczący przez klatkę.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "A gdyby wszystko potoczyło się inaczej? Gdyby rewanż naprawdę się odbył?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Khabir Nurmagaliev wciąż ma pas. Tym razem utrzymasz go w stójce i to ty narzucisz dystans.",
  "Khabir Nurmagaliev'i yen": "Pokonaj Khabira Nurmagalieva",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Wróć do wagi lekkiej: Nurmagaliev czeka tam jako mistrz.",
  "Hafif sıklet kemerini al": "Zdobądź pas wagi lekkiej",
  "Rövanş PPV payı": "Udział w PPV rewanżu",
  "🔀 Tarih yeniden yazıldı: rövanşı kazanan sensin.": "🔀 Historia napisana od nowa: rewanż jest twój.",
  "Hiç Sorun Çıkarmasaydı": "Gdyby nigdy nie sprawiał kłopotów",
  "Cezalar, kayıp yıllar, manşetlere düşen gece yarısı haberleri… Hiçbiri yaşanmasaydı?": "Zawieszenia, stracone lata, nocne nagłówki… A gdyby nic z tego się nie wydarzyło?",
  "Bu kez erken yatıyorsun, salona ilk sen giriyorsun, telefonunu kapatıyorsun.": "Tym razem kładziesz się wcześnie, pierwszy wchodzisz na salę i wyłączasz telefon.",
  "Soru basit: en iyi hâlin, kesintisiz bir seri yapsa nereye kadar gider?": "Pytanie jest proste: jak daleko zajdzie najlepsza wersja ciebie bez przerw?",
  "Üst üste 4 UCC maçı kazan": "Wygraj 4 walki w UCC z rzędu",
  "Seri {0}/4": "Seria {0}/4",
  "Bu seride 2 maçı bitirişle kazan": "Wygraj 2 walki w tej serii przed czasem",
  "Bir UCC kemerini savun": "Obroń pas UCC",
  "Temiz sezon bonusu": "Premia za czysty sezon",
  "🔀 Kesintisiz bir dahi: kimse onu durduramadı.": "🔀 Geniusz bez przerw: nikt go nie zatrzymał.",
  "Hiç Emekli Olmasaydı": "Gdyby nigdy nie przeszedł na emeryturę",
  "Herkes zirvede bıraktığını söyledi. Ama ya bırakmasaydın?": "Wszyscy mówili, że odszedłeś na szczycie. A gdybyś nie odszedł?",
  "Welter sıklette yeni bir kral var: Kamaru Usmanov. Güçlü, sabırlı, durdurulamaz.": "W wadze półśredniej jest nowy król: Kamaru Usmanov. Silny, cierpliwy, nie do zatrzymania.",
  "Profesör son bir dersi daha vermek için salona dönüyor.": "Profesor wraca na salę, by dać ostatnią lekcję.",
