  "Elli Sıfır": "Pięćdziesiąt i zero",
  "Babana verdiğin sözü tuttun ve bıraktın. Ama ya devam etseydin?": "Dotrzymałeś słowa danego ojcu i odszedłeś. A gdybyś walczył dalej?",
