  "GEÇEN HAFTA": "ZESZŁY TYDZIEŃ",
  "{0} öğrencinin maçı var: köşesinde durmak için yukarıdaki MAÇ GÜNÜ'ne dokun.": "Uczniowie mają walki ({0}): dotknij DZIEŃ WALKI powyżej, by stanąć w narożniku.",
  "Önce salondaki durumu çöz": "Najpierw rozwiąż sprawę na sali",
  "Deneme bitti": "Próba zakończona",
