  "ANTRENÖR MODU": "TRYB TRENERA",
  "Bu sefer kafese sen girmiyorsun. Garaj salonundan başla, sokaktan yetenek bul, köşelerinde dur ve onları UCC kemerine taşı.": "Tym razem to nie ty wchodzisz do klatki. Zacznij w garażowej sali, znajdź talenty na ulicy, stań w ich narożniku i doprowadź ich do pasa UCC.",
  "Yetenek avı: potansiyeli yüksek gençleri bul ve kaydet.": "Łowienie talentów: znajdź i zapisz obiecującą młodzież.",
  "Her öğrenciye antrenman odağı ver: vuruş, güreş, kondisyon…": "Daj każdemu uczniowi cel treningu: stójka, zapasy, kondycja…",
  "Maç günü köşedesin: oyun planını ve raunt arası talimatı sen verirsin.": "W dniu walki jesteś w narożniku: ty ustalasz plan i wskazówki między rundami.",
  "Antrenör seviyeni yükselt: taktik, gözcülük, motivasyon, menajerlik.": "Rozwijaj się jako trener: taktyka, skauting, motywacja, menedżerka.",
  "Salon olayları, yıl sonu Yılın Antrenörü ödülü ve dünya salon sıralaması.": "Wydarzenia na sali, nagroda Trener Roku i światowy ranking sal.",
  "HOCANIN ADI": "IMIĘ TRENERA",
