  "Erken durdurma: daha savaşıyordu. Salon yuhaladı.": "Przedwczesne przerwanie: jeszcze walczył. Hala buczała.",
  "Erken durdurma: kalkmaya çalışıyordu. Salon yuhaladı.": "Przedwczesne przerwanie: próbował wstać. Hala buczała.",
  "Tam zamanında. Dövüşçüyü korudun.": "W samą porę. Ochroniłeś zawodnika.",
  "Yerinde bir karar; bazıları biraz erken dedi.": "Rozsądna decyzja, choć niektórzy uznali ją za nieco przedwczesną.",
