  "Efsane #{0}": "Legenda #{0}",
  "🏛️ TARİH YAZILDI! {0}: artık tüm zamanların 1 numarası sensin, {1} geride kaldı. +${2}, popülerlik +{3}.": "🏛️ HISTORIA! {0}: jesteś numerem 1 wszech czasów, wyprzedzasz: {1}. +${2}, popularność +{3}.",
  "🏛️ Rekor: {0} listesinde {1} dövüşçüsünü geçtin, sıran #{2}. +${3}, popülerlik +{4}.": "🏛️ Rekord: na liście „{0}” wyprzedzasz: {1}. Twoje miejsce #{2}. +${3}, popularność +{4}.",
  "UCC Tarihi": "Historia UCC",
  "{0} tarihin 1 numarası: {1}. Bu rekor uzun süre konuşulacak.": "{0}, numer 1 w historii: {1}. O tym rekordzie będzie się długo mówić.",
  "📰 {0}: {1} rekoruna bir adım kaldı!": "📰 {0}: jeden krok do rekordu ({1})!",
  "Nakavtçı": "Nokauter",
  "Yumruğun konuşuyor. Sert vuruşların rakibi daha sık sarsar.": "Twoje pięści mówią za ciebie. Mocne ciosy częściej wstrząsają rywalem.",
  "Boğucu Güreşçi": "Duszący zapaśnik",
  "Yere inen kalkamıyor. Yerde kilit fırsatın daha sık gelir.": "Kto upadnie, ten nie wstaje. Okazje do poddania pojawiają się częściej.",
  "Taktisyen": "Taktyk",
  "Aklınla dövüşüyorsun. Rakip seni daha geç okur, köşen zaafları daha çabuk bulur.": "Walczysz głową. Rywal później cię rozgryza, a narożnik szybciej znajduje słabości.",
  "Salonu ayağa kaldırıyorsun. Galibiyetler daha çok popülerlik getirir.": "Podrywasz halę na nogi. Wygrane dają więcej popularności.",
  "{0} Dövüş kimliğin oluştu: {1}! {2}": "{0} Twoja tożsamość walki się ukształtowała: {1}! {2}",
  "{0} Kimliğin değişti: artık bir {1}. {2}": "{0} Twoja tożsamość się zmieniła: teraz {1}. {2}",
  "{0} için herkes aynı şeyi söylüyor: {1}.": "O {0} wszyscy mówią to samo: {1}.",
  "🗞️ {0}: \"Sert vurduğunu biliyorum. Çenemi çalıştırdım.\"": "🗞️ {0}: „Wiem, że mocno bijesz. Pracowałem nad szczęką.”",
  "🗞️ {0} kampında tek konu: nakavtçıya karşı nasıl ayakta kalınır?": "🗞️ W obozie {0} jeden temat: jak ustać przeciw nokauterowi.",
  "🗞️ {0} bütün kampı güreş savunmasıyla geçirdi: \"Beni yere indiremeyecek.\"": "🗞️ {0} cały obóz ćwiczył obronę obaleń: „Nie sprowadzisz mnie do parteru.”",
  "🗞️ {0}: \"Herkes yerde boğuluyor, ben boğulmayacağım.\"": "🗞️ {0}: „Wszyscy duszą się w parterze. Ja nie.”",
  "🗞️ {0}: \"Çok düşünüyor. Ona düşünecek vakit bırakmayacağım.\"": "🗞️ {0}: „Za dużo myślisz. Nie dam ci czasu na myślenie.”",
  "🗞️ {0} kampı senin maçlarını kare kare izliyor.": "🗞️ Obóz {0} analizuje twoje walki klatka po klatce.",
  "🗞️ {0}: \"Kafes sirk değil. Şovunu bitireceğim.\"": "🗞️ {0}: „Klatka to nie cyrk. Skończę twoje show.”",
  "🗞️ {0} basına konuştu: \"Bu kadar gösteriş yeter.\"": "🗞️ {0} powiedział prasie: „Dość popisów.”",
