  "Şu an geçiş reklamı yok, ödüller reklamsız geliyor. Tadını çıkar!": "Teraz nie ma reklam pełnoekranowych, a nagrody są bez reklam. Korzystaj!",
  "10 reklam izledin, 1 saat senin: geçiş reklamı yok, ödüller reklamsız. İstediğin zaman başlat.": "Obejrzałeś 10 reklam i masz 1 godzinę: bez reklam pełnoekranowych, nagrody bez reklam. Uruchom, kiedy chcesz.",
