  "Hırslı": "Ambitny",
  "Sürekli dövüşmek ister, zor maçlardan kaçmaz. Bekletilmekten nefret eder.": "Chce walczyć cały czas i nie unika trudnych walk. Nienawidzi czekać.",
  "Sadık": "Lojalny",
  "Sana güvenir, kolay kolay gitmez. Ama kırılırsa unutmaz.": "Ufa ci i nie odchodzi łatwo. Ale zraniony, nie zapomina.",
