  "Yetenekli ama kamptan kaytarır. Gelişimi yavaş, sürprizi bol.": "Utalentowany, ale obija się na obozie. Rozwija się wolno, pełen niespodzianek.",
  "Şov adamı": "Showman",
  "Kameraları sever. Takipçi ve sponsor getirir, başını da belaya sokar.": "Kocha kamery. Przyciąga fanów i sponsorów, a przy okazji kłopoty.",
  "Paragöz": "Pazerny",
  "Önce para. Daha iyi teklifi duyunca kapıyı çalan ilk kişidir.": "Najpierw pieniądze. Pierwszy puka do drzwi, gdy pojawia się lepsza oferta.",
