  "Daha üst ligden teklif gelirse bedelsiz ayrılırsın.": "Jeśli ofertę złoży wyższa liga, odchodzisz za darmo.",
  "Münhasırlık": "Wyłączność",
  "Organizasyon ister: ücret +%15, ama başka hiçbir teklife bakamazsın.": "Organizacja tego żąda: gaża +15%, ale nie możesz patrzeć na żadne inne oferty.",
  "Sakatlık güvencesi": "Ochrona przy kontuzji",
  "Sakatken kadrodan çıkarılamaz, maaşın yarısı ödenir.": "Nie można go zwolnić w czasie kontuzji, wypłacana jest połowa gaży.",
