  "Sıfırdan": "Od zera",
  "Elinde tek bir sokak dövüşçüsü ve kirası ödenmemiş bir bodrum ofis var. Her şey sana bağlı.": "Masz tylko jednego ulicznego zawodnika i biuro w piwnicy z niezapłaconym czynszem. Wszystko zależy od ciebie.",
  "Tek yıldız": "Jedna gwiazda",
  "Kadronda bir UCC şampiyonu var, ama sözleşmesi bitmek üzere ve rakip ajanslar kapıda. Onu kaybetme.": "Masz w składzie mistrza UCC, ale kontrakt zaraz wygasa, a konkurencyjne agencje stoją pod drzwiami. Nie strać go.",
  "Batık ajansı kurtar": "Ratuj tonącą agencję",
  "Önceki menajerden borç ve sana küskün üç dövüşçü devraldın. Bir yılda borcu kapat.": "Odziedziczyłeś długi po poprzednim menedżerze i trzech urażonych zawodników. Spłać dług w ciągu roku.",
  "Yurt dışı yetenekleri": "Talenty z zagranicy",
  "Brezilya ve Dağıstan'dan iki genç yetenek getirdin. Vize, dil ve gurbet sorunlarıyla yıldız yap.": "Sprowadziłeś dwa młode talenty z Brazylii i Dagestanu. Zrób z nich gwiazdy mimo wiz, bariery językowej i tęsknoty za domem.",
  "Menajer": "Menedżer",
  "{0} Yönetim": "{0} Management",
  "İlk yılında bir dövüşçünü bölgesel lige taşı.": "W pierwszym roku wprowadź jednego zawodnika do ligi regionalnej.",
  "Abi, otoparktaki dövüşleri bırakıp gerçek bir kafese çıkmak istiyorum. Sana güveniyorum. Beni bir yere götür.": "Bracie, chcę skończyć z walkami na parkingach i wejść do prawdziwej klatki. Ufam ci. Zabierz mnie gdzieś.",
  "{0} ile yeni sözleşme imzala, onu rakip ajanslara kaptırma.": "Podpisz nowy kontrakt z {0} i nie oddaj go konkurencji.",
  "Sözleşmem bir maç sonra bitiyor. Telefonum susmuyor, herkes beni istiyor. Sen beni neden tutmalıyım, onu düşünüyorum.": "Mój kontrakt kończy się po jeszcze jednej walce. Telefon się urywa, wszyscy mnie chcą. Zastanawiam się, czemu miałbym zostać z tobą.",
  "Bir yıl içinde borcu kapat (para sıfırın üstüne çıksın).": "Spłać dług w ciągu roku (wyjdź z kasą ponad zero).",
  "Ajansınızın {0} borcu bulunmaktadır. Kira ödemeleri devam ettikçe borç büyüyecektir.": "Dług twojej agencji wynosi {0}. Będzie rósł, dopóki naliczany jest czynsz.",
  "Eski menajer paramızı yedi. Sen farklı mısın, göreceğiz.": "Poprzedni menedżer przejadł nasze pieniądze. Zobaczymy, czy ty jesteś inny.",
  "İki yeteneğinden birini büyük lige taşı.": "Wprowadź jeden z dwóch talentów do głównej ligi.",
  "Burası çok soğuk, abi. Annem her gün arıyor. Ama söz verdim, kemerle döneceğim.": "Tu jest strasznie zimno, bracie. Mama dzwoni codziennie. Ale obiecałem, wrócę z pasem.",
  "Ofis dolu. Yeni dövüşçü için ofisi büyüt ya da birini bırak.": "Biuro jest pełne. Powiększ biuro dla nowego zawodnika albo kogoś zwolnij.",
  "İmza parası için yeterli paran yok.": "Nie masz dość pieniędzy na premię za podpis.",
  "{0} teklifini reddetti ve {1} ile anlaştı.": "{0} odrzucił twoją ofertę i podpisał z {1}.",
  "Hafta {0}: {1} kadroya katıldı (%{2}).": "Tydzień {0}: {1} dołączył do składu ({2}%).",
  "✍️ {0} ajansına katıldı!": "✍️ {0} dołączył do agencji!",
  "Hafta {0}: {1} ile yollar ayrıldı.": "Tydzień {0}: rozstałeś się z {1}.",
  "Hafta {0}: Çıkış maddesi işledi, {1} bedelsiz ayrıldı.": "Tydzień {0}: zadziałała klauzula odejścia, {1} odszedł za darmo.",
  "Hafta {0}: {1} sözleşmesini {2} bedelle feshetti.": "Tydzień {0}: {1} wykupił kontrakt za {2}.",
  "{0}! Rüya gibi. Bunu sana borçluyum.": "{0}! Jak we śnie. Zawdzięczam to tobie.",
  "Annemi aradım, ağladı. {0} sözleşmesi, inanamıyorum.": "Zadzwoniłem do mamy, płakała. Kontrakt z {0}, nie mogę uwierzyć.",
  "Daha yeni başlıyoruz. {0}'de herkes adımı öğrenecek.": "Dopiero zaczynamy. W {0} wszyscy poznają moje nazwisko.",
  "Hafta {0}: {1} için {2} ile {3} maçlık sözleşme ({4}/maç).": "Tydzień {0}: kontrakt na {3} walki dla {1} z {2} ({4}/walka).",
  "📝 {0} artık {1} dövüşçüsü.": "📝 {0} jest teraz zawodnikiem {1}.",
  "🗓️ {0} – {1} maçı {2}. haftada.": "🗓️ {0} – {1} w tygodniu {2}.",
  "{0}: “Teklifimiz ortada. Dinliyoruz.”": "{0}: „Nasza oferta jest na stole. Słuchamy.”",
  "{0}: “Son teklifimiz {1}. İmzala ya da yolumuza bakalım.”": "{0}: „Nasza ostateczna oferta to {1}. Podpisz albo rozchodzimy się.”",
  "{0}: “Tamam, {1} olsun.”": "{0}: „Dobra, niech będzie {1}.”",
  "{0}: “Peki. Maç başı {1}.”": "{0}: „W porządku. {1} za walkę.”",
  "{0}: “Zorluyorsun ama olur: {1}.”": "{0}: „Naciskasz, ale niech będzie: {1}.”",
  "{0}: “Bütçeyi zorluyorsun. {1} yapabiliriz.”": "{0}: „Naciągasz budżet. Możemy dać {1}.”",
  "{0}: “Kazanırsa hak eder. Bonus {1}.”": "{0}: „Jak wygra, zasłuży. Premia {1}.”",
  "{0}: “Münhasırlık mı? Seve seve. Ücrete %15 ekliyoruz.”": "{0}: „Wyłączność? Chętnie. Dokładamy 15% do gaży.”",
  "{0}: “{1}, kabul. Sözleşmeye yazıyoruz.”": "{0}: „{1}, zgoda. Wpisujemy do kontraktu.”",
  "{0}: “Çıkış maddesi mi? Dövüşçüne yatırım yapıyoruz, kaçmasına izin vermeyiz.”": "{0}: „Klauzula odejścia? Inwestujemy w twojego zawodnika, nie pozwolimy mu uciec.”",
