  "Salon karıştı, klip milyonlarca izlendi. Bilet satışları uçtu, ama rakip artık çok hırslı.": "Sala eksplodowała, klip ma miliony wyświetleń. Bilety schodzą jak szalone, ale rywal jest teraz nakręcony.",
  "Manşetlerdesiniz. Rakip kampı “onu susturacağız” dedi.": "Jesteście na nagłówkach. Obóz rywala zapowiedział: „Zamkniemy mu usta”.",
  "Patron memnun: “Böyle dövüşçüleri severiz.”": "Szef zadowolony: „Lubimy takich zawodników.”",
  "Kısa cevaplar, soğuk bakışlar. Dövüşçün tamamen maça odaklı.": "Krótkie odpowiedzi, zimne spojrzenia. Zawodnik w pełni skupiony na walce.",
  "Araya girdin, kriz büyümedi. Fotoğraflar yine de olay oldu.": "Wkroczyłeś i kryzys nie urósł. Zdjęcia i tak obiegły sieć.",
  "Şov oldu, ama komisyon {0} para cezası kesti.": "Było show, ale komisja nałożyła karę {0}.",
  "Görüntüler her yerde. Herkes cumartesiyi bekliyor.": "Nagrania są wszędzie. Wszyscy czekają na sobotę.",
  "Omzundan tutup kenara çektin. Gözleri hâlâ yanıyor, ama artık kontrol sende.": "Złapałeś go za ramię i odciągnąłeś. Oczy wciąż mu płoną, ale teraz to ty masz kontrolę.",
  "Köşe başını salladı: “Tam düşündüğümüz şey.”": "Narożnik pokiwał głową: „Dokładnie o tym myśleliśmy.”",
  "Antrenör notu okuyup gülümsedi. Plan net.": "Trener przeczytał notkę i się uśmiechnął. Plan jest jasny.",
  "Antrenör kaşlarını çattı: “Onunla yerde mi? Emin misin?”": "Trener zmarszczył brwi: „Z nim w parterze? Jesteś pewien?”",
  "Köşe notu aldı. Fena bir plan değil, ama en iyisi de değil.": "Narożnik dostał notkę. Niezły plan, ale nie najlepszy.",
