  "Büyük oynayalım: {0} karşısında {1} ({2}). Sabit ücret mi, yoksa PPV satışlarından pay mı? Teklifler sekmesinde.": "Zagrajmy na grubo: {1} ({2}) kontra {0}. Stała gaża czy udział w sprzedaży PPV? Szczegóły w zakładce Oferty.",
