  "Sana açık konuşayım: {0} yaşındayım. İki yıl içinde kemer yoksa eldivenleri asacağım. Bu benim son şansım.": "Powiem ci szczerze: mam {0} lat. Jeśli w dwa lata nie będzie pasa, wieszam rękawice. To moja ostatnia szansa.",
  "Kızım her gece soruyor: “Baba, kemer ne zaman?” Ona söz verdim. Bir yıl içinde bir kemer getireceğim, hangi ligde olursa olsun.": "Córka co wieczór pyta: „Tato, kiedy pas?” Obiecałem jej. Przyniosę pas w ciągu roku, w dowolnej lidze.",
  "Herkes beni bitti sanıyordu. Yaşlı kurt hâlâ ısırıyor, değil mi?": "Wszyscy myśleli, że jestem skończony. Stary wilk wciąż gryzie, prawda?",
  "Kızım son maçımı okulda arkadaşlarına izletmiş. Öğretmeni aradı, gülmekten öldük.": "Córka pokazała moją ostatnią walkę kolegom w szkole. Dzwoniła nauczycielka, pokładaliśmy się ze śmiechu.",
  "Yaptık. Kimse inanmazken sen inandın. Bu kemer ikimizin, ortak.": "Udało się. Wierzyłeś, gdy nikt nie wierzył. Ten pas jest nasz, wspólniku.",
  "Kemeri kızımın beline taktım. Ona bol geldi, ama gözleri… Bunu sana borçluyum.": "Założyłem pas córce. Był na nią ogromny, ale jej oczy… Zawdzięczam ci to.",
  "📖 Hikâye tamamlandı: {0} ({1}) · itibar +5": "📖 Historia zakończona: {0} ({1}) · reputacja +5",
  "Hafta {0}: 📖 {1}: “{2}” hikâyesi mutlu sonla bitti.": "Tydzień {0}: 📖 {1}: historia „{2}” skończyła się szczęśliwie.",
  "Söz sözdür. Eldivenleri asıyorum. Kemer olmadı, ama yanımda sen vardın. Teşekkürler.": "Słowo to słowo. Wieszam rękawice. Pasa nie było, ale ty byłeś przy mnie. Dzięki.",
  "📖 {0} kemersiz veda etti.": "📖 {0} pożegnał się bez pasa.",
  "Bir yıl geçti. Kızım artık sormuyor. Bu daha kötü.": "Minął rok. Córka już nie pyta. To gorsze.",
