  "{0} yine antrenmana gelmedi. Mahalledeki eski arkadaşlarıyla takılıyor, evde kavga bitmiyor. Bu çocuk kaybolacak.": "{0} znowu nie przyszedł na trening. Kręci się ze starymi kumplami z osiedla, w domu ciągłe kłótnie. Ten chłopak się zgubi.",
  "Salonun yanına oda tut, oraya taşınsın ({0}).": "Wynajmij pokój obok sali, niech się tam przeprowadzi ({0}).",
