  "Bu onun özel hayatı, karışmam.": "To jego prywatne życie, nie wtrącam się.",
  "Sen olmasan o sokaklarda kaybolup giderdim. Şimdi büyük ligdeyim. Annem ilk kez maçımı izleyecek.": "Bez ciebie zgubiłbym się na tych ulicach. Teraz jestem w głównej lidze. Mama pierwszy raz zobaczy moją walkę.",
  "📖 {0} sokaktan büyük lige uzandı · itibar +4": "📖 {0} przeszedł drogę z ulicy do głównej ligi · reputacja +4",
  "Yeni odasına taşındı. İlk hafta her sabah ilk o geldi. (Güç +2)": "Przeprowadził się do nowego pokoju. Przez pierwszy tydzień codziennie przychodził pierwszy. (Siła +2)",
  "Annesi ağladı, babası elini sıktı. Ev sakinleşti, çocuk salona döndü.": "Matka płakała, ojciec uścisnął ci dłoń. W domu się uspokoiło, chłopak wrócił na salę.",
  "Babası kapıyı yüzüne kapattı. Çocuk arada kaldı.": "Ojciec zatrzasnął ci drzwi przed nosem. Chłopak został między młotem a kowadłem.",
  "İki hafta sonra bir gece kavgasından karakola düştü. Eskisi gibi değil artık.": "Dwa tygodnie później nocna bójka skończyła się na komisariacie. Nie jest już taki sam.",
  "Bir süre kayboldu, sonra kendiliğinden döndü. Şanslısın.": "Na jakiś czas zniknął, potem wrócił sam. Miałeś szczęście.",
