  "Tek seferlik alım: sınırsız ajans kariyeri, UCC sözleşmeleri, şampiyonlar ve Yılın Menajeri ödülü.": "Jednorazowy zakup: nieograniczone kariery agencji, kontrakty UCC, mistrzowie i nagroda Menedżera Roku.",
