  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "Tym razem to nie ty wchodzisz do klatki. Kariera, pieniądze i zdrowie twoich zawodników są w twoim telefonie.",
  "Telefonun hiç susmaz: dövüşçüler, patronlar, gazeteciler ve rakip menajerler. Her cevabın bir sonucu var.": "Telefon nigdy nie milknie: zawodnicy, szefowie, dziennikarze i konkurencyjni menedżerowie. Każda odpowiedź ma konsekwencje.",
  "Organizasyonların gizli bütçesine karşı pazarlık yap; rövanş, çıkış ve sakatlık maddeleri yıllar sonra işine yarar.": "Negocjuj z ukrytym budżetem organizacji; klauzule rewanżu, odejścia i kontuzji opłacą się po latach.",
  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Szukaj talentów, podpisuj młodych, negocjując prowizję, i bądź szybszy od konkurencji.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "A jeśli dwóch twoich zawodników idzie po ten sam pas? Organizacja zechce ich ze sobą zestawić.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "Lekarz ostrzega, pieniądze wzywają. Zdrowie zawodnika czy dzień wypłaty?",
