  "Dövüşçülerin kariyeri telefonunda: pazarlık yap, şampiyon çıkar": "Kariera twoich zawodników w telefonie: negocjuj i wychowuj mistrzów",
  "Hakem, Antrenör ve Menajer Modu, bütün efsaneler, reklamsız oyun ve 6 kozmetik paket.": "Tryb Sędziego, Trenera i Menedżera, wszystkie legendy, gra bez reklam i 6 pakietów kosmetycznych.",
  "Hakem, Antrenör ve Menajer Modu ile Tam Paket'i tamamla": "Uzupełnij Pełny Pakiet o Tryb Sędziego, Trenera i Menedżera",
  "Reklamsız oyun, ödüller anında, 5 kariyer yuvası, bütün efsaneler ve Altın Seri. Hakem, Antrenör ve Menajer Modu dahil değil.": "Gra bez reklam, nagrody od razu, 5 slotów kariery, wszystkie legendy i Złota Seria. Tryb Sędziego, Trenera i Menedżera nie jest wliczony.",
  "+{0} ile Tam Paket: Hakem, Antrenör, Menajer Modu ve 6 kozmetik paket de gelsin": "Pełny Pakiet za +{0}: dostajesz też Tryb Sędziego, Trenera i Menedżera oraz 6 pakietów kosmetycznych",
  "Tam Paket'e yükselt: Hakem, Antrenör, Menajer Modu ve 6 kozmetik paket": "Przejdź na Pełny Pakiet: Tryb Sędziego, Trenera i Menedżera oraz 6 pakietów kosmetycznych",
  "Menajer Modu: kendi ajansın, kendi şampiyonların": "Tryb Menedżera: własna agencja, własni mistrzowie",
  "Kabus": "Koszmar",
  "Oyunu kolay bulanlar için. Rakipler çok güçlü ve taktiğini çabuk okur, ücretler %40 az, gelişim yavaş, sakatlıklar kalıcı iz bırakabilir. Efsane puanın 1,5 kat sayılır.": "Dla tych, którym gra wydaje się łatwa. Rywale są bardzo silni i szybko czytają twoją taktykę, gaże są o 40% niższe, rozwój powolny, a kontuzje mogą zostawić trwały ślad. Punkty legendy liczą się x1,5.",
  "Kabustan Uyanan": "Przebudzony z Koszmaru",
  "Kabus zorluğunda herhangi bir kemer kazan.": "Zdobądź dowolny pas na poziomie Koszmar.",
  "Kabusun Efendisi": "Pan Koszmaru",
  "Kabus zorluğunda UCC kemerini kazan.": "Zdobądź pas UCC na poziomie Koszmar.",
  "💀 Kabus: {0} kalıcı iz bıraktı. {1} -1.": "💀 Koszmar: {0} zostawiła trwały ślad. {1} -1.",
  "Nakavt olmak çenende derin iz bıraktı. Çene -{0}.": "Nokaut zostawił głęboki ślad na twojej szczęce. Szczęka -{0}.",
  "Kabus zorluğunda bir kemer kazan": "Zdobądź pas na poziomie Koszmar",
  "Kabus zorluğunda UCC kemerini kazan": "Zdobądź pas UCC na poziomie Koszmar",
  "Kabus Kafesi": "Klatka Koszmaru",
  "Kabus Kartı": "Karta Koszmaru",
  "Kabus Dumanı": "Dym Koszmaru",
  "YOL Evreni": "Uniwersum YOL",
  "Kariyer yuvası {0}": "Slot kariery {0}",
  "YOL EVRENİ": "UNIWERSUM YOL",
  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Wszystkie twoje tryby dzieją się w jednym świecie. Zawodnicy z kariery pojawiają się jako rywale w Trybie Menedżera, a zawodnicy z Trybu Menedżera stają naprzeciw twojej kariery w głównych ligach i w UCC.",
  "ÇAPRAZ MAÇ": "STARCIA",
  "ÇAPRAZ MAÇLAR": "STARCIA MIĘDZY TRYBAMI",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Jeszcze nie było starć między trybami. Gdy wejdziesz do głównych lig i w Trybie Menedżera pojawią się oferty, twoi zawodnicy się spotkają.",
  "Bağlantı için iki tarafta da dövüşçü gerekir: aktif bir kariyer ve Menajer Modu'nda aynı sıklette bir dövüşçü.": "Potrzebujesz zawodników po obu stronach: aktywnej kariery i zawodnika w tej samej kategorii wagowej w Trybie Menedżera.",
  "KARİYER DÖVÜŞÇÜLERİN": "TWOI ZAWODNICY Z KARIERY",
  "Henüz kariyerin yok.": "Nie masz jeszcze kariery.",
  "MENAJER MODU DÖVÜŞÇÜLERİN": "TWOI ZAWODNICY Z TRYBU MENEDŻERA",
  "Menajer Modu'nda ajans kurup dövüşçü imzaladığında burada görünürler.": "Gdy założysz agencję i podpiszesz zawodników w Trybie Menedżera, pojawią się tutaj.",
  "Bütün modların aynı dünyada: dövüşçülerin birbirinin karşısına çıkar": "Wszystkie tryby w jednym świecie: twoi zawodnicy stają naprzeciw siebie",
  "🌐 YOL Evreni: kariyer modundaki dövüşçün!": "🌐 Uniwersum YOL: twój zawodnik z kariery!",
  "🌐 YOL Evreni: Menajer Modu'ndaki dövüşçün!": "🌐 Uniwersum YOL: twój zawodnik z Trybu Menedżera!",
  "Menajer: {0}, kariyer modundaki dövüşçün {1} ile karşılaştı ve {2}.": "Menedżer: {0} zmierzył się z twoim zawodnikiem z kariery {1} i {2}.",
  "Kariyer: {0}, Menajer Modu'ndaki dövüşçün {1} ile karşılaştı ve {2}.": "Kariera: {0} zmierzył się z twoim zawodnikiem z Trybu Menedżera {1} i {2}.",
