  "Kendi dövüşçünün adını ve lakabını, rakiplerinin isimlerini ve istatistikleri değiştirmek Şampiyon Paketi ya da Tam Paket sahiplerine açık. Organizasyon ve UCC kadrosu editörü herkese ücretsiz.": "Zmiana imienia i pseudonimu twojego zawodnika, nazwisk rywali i statystyk jest dostępna dla posiadaczy Pakietu Mistrza lub Pełnego Pakietu. Edytor organizacji i składu UCC jest darmowy dla wszystkich.",
  "Paketlere bak": "Zobacz pakiety",
  "Düzenlenecek kariyer yok. Önce bir kariyer başlat.": "Brak kariery do edycji. Najpierw rozpocznij karierę.",
  "Kariyer kaydedildi. İstatistikler değiştiği için bu kariyer artık başarım kazanmaz.": "Kariera zapisana. Statystyki zostały zmienione, więc ta kariera nie zdobywa już osiągnięć.",
  "Kariyer kaydedildi.": "Kariera zapisana.",
