  "Değiştirirsen bu kariyer artık başarım kazanmaz ve oynayarak açılan ödüllerde sayılmaz.": "Jeśli je zmienisz, ta kariera nie zdobędzie już osiągnięć i nie będzie się liczyć do nagród zdobywanych grą.",
  "RAKİPLER": "RYWALE",
