  "Henüz düzenleme yok. Organizasyon ya da kadro düzenleyince kodun burada oluşur.": "Brak zmian. Kod pojawi się tutaj, gdy edytujesz organizację lub skład.",
  "Kodu paylaş": "Udostępnij kod",
  "YOL için editör kodum ({0} düzenleme). Oyunda Editör > Paylaş'a yapıştır: {1}": "Mój kod edytora YOL (zmian: {0}). W grze wklej go w Edytor > Udostępnij: {1}",
