  "Patron Modu": "Tryb Promotora",
  "Kendi organizasyonunu kur: kartı sen kur, kemerleri sen ver, UCC'yi geç": "Zbuduj własną federację: ty układasz karty, ty dajesz pasy, ty wyprzedzasz UCC",
  "Patron Modu: kendi organizasyonun, kendi kemerlerin": "Tryb Promotora: własna federacja, własne pasy",
  "Patron, Menajer, Antrenör ve Hakem Modu, bütün efsaneler, reklamsız oyun ve 6 kozmetik paket.": "Tryb Promotora, Menedżera, Trenera i Sędziego, wszystkie legendy, gra bez reklam i 6 pakietów kosmetycznych.",
  "Reklamsız oyun, ödüller anında, 5 kariyer yuvası, bütün efsaneler ve Altın Seri. Patron, Menajer, Antrenör ve Hakem Modu dahil değil.": "Gra bez reklam, nagrody od razu, 5 slotów kariery, wszystkie legendy i Złota Seria. Bez Trybu Promotora, Menedżera, Trenera i Sędziego.",
  "+{0} ile Tam Paket: Patron, Menajer, Antrenör, Hakem Modu ve 6 kozmetik paket de gelsin": "+{0} za Pełny Pakiet: dodatkowo Tryb Promotora, Menedżera, Trenera, Sędziego i 6 pakietów kosmetycznych",
  "Tam Paket'e yükselt: Patron, Menajer, Antrenör, Hakem Modu ve 6 kozmetik paket": "Ulepsz do Pełnego Pakietu: Tryb Promotora, Menedżera, Trenera, Sędziego i 6 pakietów kosmetycznych",
