  "Kafes seni çağırıyor. Erken geçersen gelişecek zamanın çok olur; bir yıl daha kalırsan biraz daha olgun başlarsın.": "Klatka wzywa. Przejdź wcześnie, a będziesz miał więcej czasu na rozwój; zostań rok dłużej, a zaczniesz dojrzalszy.",
