  "✓ Gençlik Yolu seçildi": "✓ Wybrano ścieżkę młodości",
  "Gençlik Yolu: 12 yaşından başla": "Ścieżka młodości: zacznij w wieku 12 lat",
  "Dövüş geçmişinin sporunda (boks, Muay Thai, grappling ya da güreş) çocukken başla. Her yıl bir karar ve bir turnuva; 18'inde MMA'ya geç. Seçmezsen hemen MMA ile başlarsın.": "Zacznij jako dziecko w sporcie swojego pochodzenia (boks, muay thai, grappling lub zapasy). Co roku decyzja i turniej; w wieku 18 lat przejście do MMA. Bez tego zaczynasz od razu w MMA.",
  "Muay Thai": "Muay Thai",
  "Grappling": "Grappling",
