  "Dört dövüş sporu liginin hepsinde kemer kazan.": "Zdobądź pas we wszystkich czterech ligach sportów walki.",
  "İleri yürü, rakibi iplere daya. Çok hasar, çok yorgunluk.": "Idź do przodu, przyciśnij go do lin. Dużo obrażeń, dużo zmęczenia.",
  "Rakip gelsin, açığını kontra yumrukla cezalandır.": "Niech podejdzie, karz luki kontrami.",
  "Jab ve ayak oyunu": "Jab i praca nóg",
  "Jab ile puan topla, ringin ortasında dön, köşeye sıkışma.": "Punktuj jabem, krąż na środku ringu, nie daj się zapędzić w róg.",
  "İleri yürü; tekme ve yumruk zinciriyle bastır.": "Idź do przodu; naciskaj seriami kopnięć i ciosów.",
  "Tekmesini yakala, açığına dirsek ve diz gönder.": "Złap kopnięcie i wyślij łokcie i kolana w lukę.",
  "Uzun mesafe": "Długi dystans",
  "Teep ve uzun tekmelerle uzakta tut, puan topla.": "Trzymaj go z dala teepami i długimi kopnięciami, zbieraj punkty.",
  "Klinç (plum)": "Klincz (plum)",
  "Ensesini kontrol et; diz ve dirsekle yıprat.": "Kontroluj kark; wykańczaj kolanami i łokciami.",
  "İndirmeye git": "Idź po obalenie",
  "Dal, yere götür; üstte pozisyon kur, kilit ara.": "Wejdź, obal go; zbuduj pozycję na górze i szukaj dźwigni.",
  "Tutuş ve fırlatma": "Chwyt i rzut",
  "Gövde kilidi ve fırlatma; üst pozisyonu kap.": "Klamra na tułów i rzut; zajmij górną pozycję.",
  "Savun ve karşıla": "Broń się i kontruj",
  "Dalışını sprawl ile kes, sonra arkasını al.": "Zatrzymaj wejście sprawlem, potem zajmij plecy.",
  "Bacağa dal": "Wejdź w nogi",
  "Tek ya da çift bacak; indirme puanını al.": "Jedna lub dwie nogi; zgarnij punkty za obalenie.",
  "Kol bağla, belden kavra; suplex ve çevirme.": "Zwiąż rękę, złap w pasie; suplex i przewrót.",
  "Dalışını kes, arkasına dön; tuş fırsatını bekle.": "Zatrzymaj wejście, obejdź za plecy; czekaj na położenie.",
  "Jabı unutma, her şey jabla başlar.": "Nie zapominaj o jabie, wszystko zaczyna się od jabu.",
  "Çeneni göğsüne göm, ellerini yukarıda tut.": "Broda w dół, ręce w górze.",
  "Gövdeye vur, kafa kendiliğinden gelir.": "Bij na korpus, głowa przyjdzie sama.",
  "İplere yaslanma, ringin ortasında kal.": "Nie opieraj się o liny, zostań na środku ringu.",
  "Vur ve çık; orada durma.": "Uderz i wyjdź; nie stój tam.",
  "Tekmesini yakala, süpür!": "Złap kopnięcie i podetnij go!",
  "Klinçte ensesini bırakma, dizle!": "W klinczu nie puszczaj karku, kolano!",
  "Ön bacağına low kick, o bacağı öldür.": "Low kicki w przednią nogę, wykończ ją.",
  "Dirsek mesafesi açıldığında gönder.": "Gdy otworzy się dystans łokcia, wyślij.",
  "Teep ile mesafeyi sen belirle.": "Ustal dystans teepem.",
  "Önce pozisyon, sonra kilit!": "Najpierw pozycja, potem dźwignia!",
  "Sırtını mindere verme, kalçanı kaçır!": "Nie oddawaj pleców, ruszaj biodrami!",
  "Kolunu dışarıda bırakıyor, kimura'ya bak.": "Zostawia rękę na zewnątrz, szukaj kimury.",
  "Ağırlığını ver, nefes aldırma.": "Daj ciężar, nie pozwól mu oddychać.",
  "Ayağa kalkmasına izin verme.": "Nie pozwól mu wstać.",
  "Bacaklarına dal, puan orada!": "Wejdź w nogi, tam są punkty!",
  "Köprü kur, sırtını yere değdirme!": "Zrób most, nie kładź łopatek!",
  "Kafa pozisyonunu kaybetme.": "Nie trać pozycji głowy.",
  "Kolunu bağla, belinden kavra!": "Zwiąż rękę, złap w pasie!",
  "Çevir onu! Tuşa bir adım kaldı.": "Przewróć go! Krok od położenia.",
