  "Tabloyu kapat": "Zamknij tabelę",
  "Tüm tablo": "Cała tabela",
  "{A} rakibini iplere dayıyor ve sol-sağ-sol hook serisini boşaltıyor!": "{A} przypiera rywala do lin i wyprowadza serię sierpowych lewy-prawy-lewy!",
  "{A} köşeye sıkıştırdı; ağır bir sağ el yüze temiz iniyor!": "{A} zamyka go w narożniku; ciężki prawy wchodzi czysto!",
  "{A} içeri girip aparkatla başlayan bir kombinasyon bağlıyor.": "{A} wchodzi i łączy kombinację zaczętą podbródkowym (uppercut).",
  "{A} başını eğip sıyrılıyor, rakip boşluğa düşüyor ve kısa bir sol hook yiyor.": "{A} robi unik, rywal leci w próżnię i zbiera krótki lewy sierpowy (hook).",
  "{A} ringin ortasında dönüp jab-kros ile puan topluyor.": "{A} krąży na środku ringu i punktuje jab-prosty.",
  "{A} ayak oyunuyla açı alıp çift jab yapıştırıyor ve çıkıyor.": "{A} pracą nóg łapie kąt, wkłada podwójny jab i wychodzi.",
  "{A} uzun jabıyla rakibin atağını daha başlamadan kesiyor.": "{A} długim jabem ucina atak rywala, zanim się zacznie.",
  "{A} ileri yürüyor; yumruk serisini sert bir orta tekmeyle bağlıyor!": "{A} idzie do przodu i kończy serię ciosów mocnym kopnięciem na korpus!",
  "{A} rakibini iplere dayayıp dirsekle tamamlanan bir kombinasyon indiriyor.": "{A} przypiera go do lin i wkłada kombinację zakończoną łokciem.",
  "{A} gövdeye tekme, kafaya kros: zincir hiç durmuyor!": "{A}: kopnięcie na korpus, prosty na głowę — łańcuch się nie kończy!",
  "{A} gelen tekmeyi yakaladı ve kontra kros patlattı!": "{A} łapie kopnięcie i odpala kontrujący prosty!",
  "{B} tekmeye gidiyor ama {A} bloklayıp sert bir low kick ile cevap veriyor.": "{B} idzie na kopnięcie, ale {A} blokuje i odpowiada mocnym low kickiem.",
  "{A} geri adım atıyor, rakip boşluğa düşüyor ve dirsek yiyor.": "{A} cofa się, rywal leci w próżnię i zbiera łokieć.",
  "{A} teep ile mesafeyi koruyor, rakip içeri giremiyor.": "{A} trzyma dystans kopnięciem teep, rywal nie może wejść.",
  "{A} uzun bir orta tekmeyle puan topluyor; gövde ses verdi.": "{A} punktuje długim kopnięciem na korpus; było słychać trafienie.",
  "{A} yüksek tekme fırlattı, gard son anda kalktı!": "{A} wyprowadza wysokie kopnięcie, garda podnosi się w ostatniej chwili!",
  "{A} plum klinç aldı, dizler gövdeye art arda iniyor!": "{A} łapie klincz plum, kolana raz za razem w korpus!",
  "{A} klinçten çıkarken kısa bir dirsek savuruyor, kaşın üstüne değdi!": "{A} wychodząc z klinczu uderza krótkim łokciem — w łuk brwiowy!",
  "{A} ensesinden çekip dizi yüze gönderdi!": "{A} ściąga głowę w dół i posyła kolano w twarz!",
  "{A} guard'ı geçip yan kontrole kuruldu, ağırlığını veriyor.": "{A} przechodzi gardę i usadawia się w kontroli bocznej, dociskając ciężarem.",
  "{A} mount'a tırmandı! Rakip altta nefes almakta zorlanıyor.": "{A} wspina się do dosiadu (mount)! Rywal pod spodem ledwo oddycha.",
  "{A} sırtı aldı, iki kanca içeride. Kilit arıyor!": "{A} zajmuje plecy, oba haki w środku. Szuka dźwigni!",
  "{A} yarım guard'dan çıkıp diz-göbek pozisyonuna geçti.": "{A} wychodzi z półgardy i przechodzi do kolana na brzuchu.",
  "{A} rakibini çevirdi; sırtı mindere yaklaşıyor, puan!": "{A} przewraca rywala; plecy coraz bliżej maty — punkty!",
  "{A} yerde kontrolü aldı, rakibin omuzlarını mindere bastırıyor.": "{A} przejmuje kontrolę w parterze, dociska barki rywala do maty.",
  "{A} köprüdeki rakibini zorluyor; tuşa çok yakın!": "{A} łamie most rywala — tuż przy położeniu na łopatki!",
  "{A} arkasına geçip rakibini yan çevirdi. İki puan!": "{A} wchodzi za plecy i przewraca rywala na bok. Dwa punkty!",
  "{A} el kavgasını kazanıyor, bilekleri kontrol edip rakibini geri itiyor.": "{A} wygrywa walkę na ręce, kontroluje nadgarstki i spycha rywala.",
  "{A} kafa kafaya tutuşta baskı kuruyor; rakip mindere doğru geriliyor.": "{A} naciska w zwarciu głowa w głowę; rywal ugina się ku macie.",
  "{A} bacaklara fint atıp rakibini dengesiz yakaladı.": "{A} markuje wejście w nogi i łapie rywala bez równowagi.",
  "{A} seviye değiştirip çift bacak dalıyor… ve rakibini mindere çarpıyor!": "{A} zmienia poziom, wchodzi w obie nogi… i wbija rywala w matę!",
  "{A} kalça atarak rakibini mindere savuruyor. Temiz fırlatma!": "{A} rzuca rywala przez biodro na matę. Czysty rzut!",
  "{A} tek bacağı yakaladı, rakibini döndürüp mindere indirdi.": "{A} łapie jedną nogę, obraca rywala i sprowadza go na matę.",
  "{A} bacağa dalıyor ama {B} sprawl ile savunuyor ve ayağa dönüyor.": "{A} wchodzi w nogę, ale {B} broni sprawlem i wraca do stójki.",
  "{A} bacağa gidiyor, {B} kalçasını geri atıp dengesini koruyor. Boşa enerji.": "{A} idzie w nogę, {B} cofa biodra i utrzymuje równowagę. Stracona energia.",
  "{A} dalış yaptı ama {B} kafasını bastırıp girişi kesti.": "{A} wchodzi, ale {B} dociska mu głowę i ucina wejście.",
